window.__LIBQ=window.__LIBQ||{};window.__LIBQ["the-gioi-hoan-my"]=window.__LIBQ["the-gioi-hoan-my"]||{};window.__LIBQ["the-gioi-hoan-my"]["q09"]=window.__LIBQ["the-gioi-hoan-my"]["q09"]||{};window.__LIBQ["the-gioi-hoan-my"]["q09"]["map"]={"updatedAt":"2026-07-24","count":169,"nodes":[{"id":"ba-ngan-khu-vuc-du-tuyen","name":"Ba ngàn khu vực dự tuyển","cn":"","capDo":"vuc","parentId":"khu-vuc-khong-nguoi","blurb":"Ba ngàn vùng dự tuyển tương ứng với ba ngàn châu, được bố trí trong khu vực không người.","detail":"Mỗi khu vực tiếp nhận người vượt ải của một châu và được ngăn cách với các khu vực khác bằng giới bích. Người đủ mạnh vẫn có thể xuyên qua giới bích để tiến vào khu vực của châu khác.","theLucLienQuan":[],"nguon":["@c0801"]},{"id":"hoa-tien-dao-va-canh-cua-tien-co","name":"Hoa Tiên đạo và cánh cửa Tiên cổ","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Lối vào Tiên cổ hiện ra khi Hoa Tiên đạo hoàn toàn nở rộ. Cánh cửa trên hoa hút những người đăng lâm đại lộ kim quang vào bên trong.","detail":"Khi cánh hoa cuối cùng mở ra, Hoa Tiên đạo phóng ba ngàn đại lộ kim quang tới các khu vực tuyển chọn. Người được kim quang bao phủ sẽ tiến tới bông hoa và đi qua cánh cửa dẫn vào Tiên cổ.","theLucLienQuan":[],"nguon":["@c0803"]},{"id":"ba-ngan-dai-lo-kim-quang","name":"Ba ngàn đại lộ kim quang","cn":"","capDo":"khac","parentId":"ba-ngan-khu-vuc-du-tuyen","blurb":"Ba ngàn con đường ánh sáng xuất phát từ Hoa Tiên đạo và trải tới toàn bộ khu vực tuyển chọn. Chúng dẫn những người đủ tư cách tới cánh cửa Tiên cổ.","detail":"Sau khi Hoa Tiên đạo nở hoàn toàn, các đại lộ kim quang bao phủ những tu sĩ được lựa chọn và đưa họ về phía bông hoa. Cát Tiềm là người đầu tiên đăng lâm một trong các con đường này.","theLucLienQuan":[],"nguon":["@c0803"]},{"id":"tien-co","name":"Tiên Cổ","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Bí thổ cổ xưa được nối với ba ngàn cánh hoa Tiên đạo và tiếp nhận gần năm trăm vạn Tôn giả. Đây là lần cuối Tiên Cổ mở ra trong kỷ nguyên.","detail":"Mỗi cánh của Hoa Tiên đạo mở một Tiên môn dẫn vào Tiên Cổ. Người tham dự phải vượt qua ba ngàn con đường đá xanh chịu áp lực của những loại đại đạo khác nhau trước khi tiến tới thế giới sặc sỡ ở cuối đường.","theLucLienQuan":["Tiên điện","Thiên Nhân tộc"],"nguon":["@c0804"]},{"id":"co-dia-co-hoa-tien-dao","name":"Cổ địa có hoa Tiên đạo","cn":"","capDo":"khac","parentId":null,"blurb":"Cổ địa nơi Hoa Tiên đạo nở đủ ba ngàn cánh và hàng triệu tu sĩ tập trung chờ Tiên Cổ mở cửa.","detail":"Tại đây, mỗi cánh hoa nâng hơn vạn tu sĩ và mở ra một Tiên môn. Những người nhen nhóm Thần Hỏa ngay trước cửa bị đại đạo quét khỏi cánh hoa.","theLucLienQuan":[],"nguon":["@c0804"]},{"id":"ba-ngan-con-duong-da-xanh","name":"Ba ngàn con đường đá xanh","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Ba ngàn con đường bên trong Tiên Cổ, mỗi đường chịu ảnh hưởng của một loại đại đạo. Áp lực tăng dần khi người tham dự tiến về phía trước.","detail":"Các con đường được ngăn cách bằng giới bích và dẫn tới thế giới sặc sỡ ở cuối đường. Thạch Hạo nghiên cứu mảnh vỡ quy tắc trên bậc đá rồi liên tiếp đánh xuyên giới bích để đổi đường.","theLucLienQuan":[],"nguon":["@c0804"]},{"id":"the-gioi-sac-so-cuoi-duong-da","name":"Thế giới sặc sỡ cuối đường đá","cn":"","capDo":"khac","parentId":"ba-ngan-con-duong-da-xanh","blurb":"Khu vực như mộng nằm ở cuối các con đường đá xanh trong Tiên Cổ. Những quái thai cổ đại hàng đầu đang tiến về nơi này.","detail":"Khi người tham dự tới gần hoặc tiến vào khu vực này, các Giáo chủ bên ngoài có thể quan sát cảnh tượng trong Tiên Cổ rõ ràng hơn qua những cánh hoa và bia ngọc.","theLucLienQuan":[],"nguon":["@c0804"]},{"id":"bac-thang-da-xanh-tien-co","name":"Bậc thang đá xanh trong Tiên cổ","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Bậc thang đá xanh nơi Thạch Hạo bị ngoại giới quan sát khi công khai thân phận thật.","detail":"Tại đây, Thạch Hạo khôi phục dung mạo, tuyên chiến với nhiều đạo thống và công khai thi triển đôi cánh Côn Bằng để tiêu diệt những kẻ đánh lén.","theLucLienQuan":["Tiên điện","Thiên quốc","Minh thổ","Thiên Nhân tộc","Yêu Long đạo môn","Hỏa Vân động","La Phù Chân cốc"],"nguon":["@c0806"]},{"id":"co-dia-co-thanh-tri-den","name":"Cổ địa có thành trì đen","cn":"","capDo":"gioi-nho","parentId":"tien-co","blurb":"Một địa vực trong Tiên cổ có rừng rậm dày đặc và tòa thành đen khổng lồ.","detail":"Một sơ đại xé lớp ngăn cách để tiến vào địa vực này. Bên trong là mặt đất rộng lớn, rừng rậm dày đặc và một tòa thành đen có nhiều sinh linh cư trú.","theLucLienQuan":[],"nguon":["@c0807"]},{"id":"sa-mac-co-hoi-nuoc-thanh-khiet","name":"Sa mạc có hơi nước thánh khiết","cn":"","capDo":"gioi-nho","parentId":"tien-co","blurb":"Một địa vực sa mạc trong Tiên cổ có hơi nước thánh khiết hiện ra ở phía cuối.","detail":"Long ngao tiến vào địa vực này. Hơi nước ở cuối sa mạc giống dấu hiệu của dòng suối sinh mệnh có thể khiến Giáo chủ động lòng, nhưng cũng có khả năng chỉ là ảo giác.","theLucLienQuan":[],"nguon":["@c0807"]},{"id":"tien-tri-mau-phuong-hoang","name":"Tiên trì máu Phượng hoàng","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Bảo địa được cho là chứa máu Phượng hoàng và thích hợp để hoàn thành lột xác.","detail":"Tiên trì được các cường giả hiểu rõ Tiên cổ lựa chọn làm nơi nhen nhóm Thần hỏa. Người tiến vào có khả năng niết bàn và hoàn thành một lần lột xác khi đột phá.","theLucLienQuan":[],"nguon":["@c0807"]},{"id":"co-dong-ky-lan","name":"Cổ động Kỳ lân","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Một thánh địa trong Tiên cổ được nhắc tới như nơi thích hợp để hoàn mỹ nhen nhóm Thần hỏa.","detail":"Cổ động Kỳ lân nằm trong số những bảo địa mà các thiên tài am hiểu Tiên cổ có thể lựa chọn để tìm kiếm bước đột phá hoàn mỹ.","theLucLienQuan":[],"nguon":["@c0807"]},{"id":"ngon-nui-ngo-dao-cua-thap-hung","name":"Ngọn núi ngộ đạo của Thập Hung","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Ngọn núi được cho là từng có Thập Hung tọa quan ngộ đạo.","detail":"Địa điểm này được xem như một thánh địa có thể tạo ra bước nhảy vọt khi người tu luyện tiến vào Thần Hỏa cảnh.","theLucLienQuan":["Thập Hung"],"nguon":["@c0807"]},{"id":"co-dia-ngoai-tien-co","name":"Cổ địa ngoài Tiên Cổ","cn":"","capDo":"khac","parentId":null,"blurb":"Cổ địa nơi Hoa Tiên đạo hiện ra trên vòm trời và tiếp dẫn người tham dự vào Tiên Cổ.","detail":"Gần năm trăm vạn Tôn giả tập trung tại đây, đứng trên các cánh hoa mang đại đạo riêng rồi đi qua những cửa ánh sáng nối vào Tiên Cổ.","theLucLienQuan":["Các Giáo chủ thượng giới"],"nguon":["@c0808"]},{"id":"khu-vuc-bot-khi-nhieu-mau","name":"Khu vực bọt khí nhiều màu","cn":"","capDo":"vuc","parentId":"tien-co","blurb":"Vùng giao hội của vô số địa giới nhiều màu bên trong Tiên cổ.","detail":"Mỗi bọt khí đại diện cho một địa vực rộng lớn như tiểu thiên thế giới, được khí hỗn độn bao bọc và có thể nối thông với các khu vực mang hoàn cảnh, cơ duyên cùng hung hiểm khác nhau.","theLucLienQuan":[],"nguon":["@c0811"]},{"id":"hang-rong-than-bi","name":"Hang rồng thần bí","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Bảo địa nằm trong tiểu thiên thế giới thuộc Tiên cổ, có giao long Thiên Thần bị xích vào cọc đá canh giữ cửa động.","detail":"Hang rồng nằm trong một tiểu thiên thế giới thuộc Tiên cổ. Giao long Thiên Thần to như núi bị xích sắt phù văn khóa vào cọc đá cạnh cửa hang để canh giữ. Truyền nhân Tiên điện từng định chọn nơi này làm bảo địa nhen Thần hỏa nhưng bị giao long truy sát phải bỏ chạy. Bảo địa vẫn chưa được khai phá.","theLucLienQuan":[],"nguon":["@c0812"]},{"id":"ba-ngan-tieu-thien-the-gioi","name":"Ba ngàn tiểu thiên thế giới","cn":"","capDo":"gioi-nho","parentId":"tien-co","blurb":"Các tiểu thiên thế giới nằm trong những vùng giống như bọt khí của Tiên cổ. Đây là nơi hàng triệu Tôn giả tìm kiếm vật chất thần thánh và tiến hành thành thần.","detail":"Khoảng bảy phần mười người tham dự đã hoàn tất thành thần tại các tiểu thiên thế giới, sau đó hoạt động săn giết và tranh đoạt bắt đầu gia tăng.","theLucLienQuan":[],"nguon":["@c0813"]},{"id":"toa-thanh-den-trong-tieu-thien-the-gioi","name":"Tòa thành đen trong tiểu thiên thế giới","cn":"","capDo":"thanh","parentId":"ba-ngan-tieu-thien-the-gioi","blurb":"Một tòa thành đen khổng lồ nằm trong tiểu thiên thế giới của Tiên cổ. Các sinh linh mặc giáp từ bên trong lao ra tàn sát người ngoại lai.","detail":"Những sinh linh mặc giáp có dáng vẻ như tiên binh, biến khu vực quanh thành thành một hiểm địa đối với người tham dự Tiên cổ.","theLucLienQuan":[],"nguon":["@c0813"]},{"id":"co-gioi-con-trung","name":"Cổ giới côn trùng","cn":"","capDo":"gioi-nho","parentId":"tien-co","blurb":"Một cổ giới mờ ảo đầy những loài sâu có thể hóa thành từng tia sáng. Bầy côn trùng tại đây đủ sức giết cả những cường giả vừa thành thần.","detail":"Vô số sâu đã gặm hơn mười cường giả thành thần chỉ còn xương trắng, cho thấy hiểm họa bản địa trong Tiên cổ không kém sự tranh đấu giữa những người tham dự.","theLucLienQuan":[],"nguon":["@c0813"]},{"id":"tieu-thien-the-gioi-long-lay","name":"Tiểu thiên thế giới lộng lẫy","cn":"","capDo":"gioi-nho","parentId":"ba-ngan-tieu-thien-the-gioi","blurb":"Tiểu thiên thế giới có tinh khí thiên địa dồi dào mà Thạch Hạo tiến vào sau khi tỉnh lại.","detail":"Thạch Hạo chọn nơi này để bổ sung tinh khí và thần lực sau quá trình nung luyện khiến sinh cơ suy kiệt. Sơ đại của Yêu Long đạo môn đang bế quan trong một dòng thần tuyền tại đây.","theLucLienQuan":["Yêu Long đạo môn"],"nguon":["@c0814"]},{"id":"than-tuyen-duoi-doc-da","name":"Thần tuyền dưới dốc đá","cn":"","capDo":"khac","parentId":"tieu-thien-the-gioi-long-lay","blurb":"Dòng thần tuyền phun ráng lành và thần hà, chứa tinh khí nồng đậm.","detail":"Sơ đại của Yêu Long đạo môn hóa thành một con giao long trong suốt, bơi lội và bế quan bên trong thần tuyền. Hơn mười tu sĩ Thần Hỏa cảnh canh giữ khu vực này và ngăn Thạch Hạo tiếp cận.","theLucLienQuan":["Yêu Long đạo môn"],"nguon":["@c0814"]},{"id":"tieu-thien-the-gioi-chien-truong","name":"Tiểu thiên thế giới chiến trường","cn":"","capDo":"gioi-nho","parentId":"ba-ngan-tieu-thien-the-gioi","blurb":"Tiểu thiên thế giới nơi Thạch Hạo giao chiến với Yêu Dịch và nhóm tu sĩ Yêu Long đạo môn.","detail":"Cuộc giao chiến diễn ra quanh thần tuyền, làm nhiều vách núi và núi đá nổ tung. Tại đây Thạch Hạo giết sạch đội ngũ cường giả đã thành thần của Yêu Long đạo môn và chém đầu Yêu Dịch.","theLucLienQuan":["Yêu Long đạo môn"],"nguon":["@c0815"]},{"id":"day-nui-noi-yeu-dich-tu-tran","name":"Dãy núi nơi Yêu Dịch tử trận","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Một dãy núi trở thành chiến trường giữa Thạch Hạo và nhóm Yêu Long đạo môn.","detail":"Sau trận chiến, mặt đất nhuốm máu và đầy sinh linh Yêu Long đạo môn ngã xuống; Yêu Dịch bị chém đầu, phá mi tâm và dập tắt nguyên thần tại đây.","theLucLienQuan":["Yêu Long đạo môn"],"nguon":["@c0816"]},{"id":"dong-suoi-bao-dich","name":"Dòng suối bảo dịch","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Bảo địa thần thánh chứa linh dịch sền sệt và tinh hoa thần tính tích lũy lâu năm.","detail":"Thạch Hạo ngồi trong dòng suối suốt một ngày một đêm để luyện hóa tinh hoa chữa thương, khiến nơi này gần như khô cạn.","theLucLienQuan":[],"nguon":["@c0816"]},{"id":"con-duong-da-dao-hoa","name":"Con đường đá đạo hỏa","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Con đường đá nơi Thạch Hạo từng chịu một trăm lẻ tám luồng đạo hỏa thiêu đốt.","detail":"Đạo hỏa thiêu đốt gân mạch, huyết nhục và xương cốt của Thạch Hạo, đồng thời đốt sáng một trăm lẻ tám chùm sáng trong cơ thể hắn trên con đường thành thần.","theLucLienQuan":[],"nguon":["@c0816"]},{"id":"tieu-the-gioi-sinh-co-bung-bung","name":"Tiểu thế giới sinh cơ bừng bừng","cn":"","capDo":"gioi-nho","parentId":"tien-co","blurb":"Một tiểu thế giới rộng mấy vạn dặm, tràn đầy linh khí và sinh cơ.","detail":"Nơi đây có núi non, cỏ cây phát sáng, linh dược và dị quả. Thạch Hạo tìm người Minh tộc suốt hai ngày, hái được nhiều bảo dược rồi phát hiện Hồng Hoàng đang bị truy sát.","theLucLienQuan":["Minh thổ"],"nguon":["@c0816"]},{"id":"khu-di-tich-duoi-huyet-nguyet","name":"Khu di tích dưới huyết nguyệt","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Khu di tích hoang phế nằm dưới huyết nguyệt trong thế giới Tiên cổ, được Hồng Hoàng nghi là nơi cất giấu một vườn thuốc cổ.","detail":"Nơi đây không còn kiến trúc nguyên vẹn, chỉ có gạch vụn và cây lớn. Tại khu vực trung tâm, tiên quang cùng tiếng ca thỉnh thoảng xuất hiện; sau đó rùa trắng cõng cô gái áo trắng hiện ra giữa dược hương nồng đậm.","theLucLienQuan":["Minh tộc"],"nguon":["@c0817"]},{"id":"bach-cot-son","name":"Bạch cốt sơn","cn":"","capDo":"khac","parentId":"minh-tho-dia-danh","blurb":"Tòa núi xương lơ lửng trong hư không và bị hắc vụ bao phủ.","detail":"Minh chủ cùng người Minh tộc tụ tập tại đây để theo dõi hình ảnh Thạch Hạo trên bia đá. Họ tỏ ra âm trầm và tức giận khi chứng kiến hắn tiêu diệt Minh nhân rồi công khai chê thi thể Minh tộc không thể dùng làm thức ăn.","theLucLienQuan":["Minh tộc","Minh thổ"],"nguon":["@c0817"]},{"id":"vuon-thuoc-trong-di-tich-tien-co","name":"Vườn thuốc trong di tích Tiên cổ","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Vườn thuốc cổ nằm trong khu phế tích dưới huyết nguyệt, được đại trận chia thành năm tầng không gian.","detail":"Mỗi tầng của vườn thuốc đều có trận văn nguy hiểm và những cây thuốc quý còn sót lại. Tầng cuối chứa linh thổ vàng kim, đại trận tương đối hoàn chỉnh và Hư Thiên thần đằng đang bị giam giữ.","theLucLienQuan":["Minh tộc"],"nguon":["@c0818"]},{"id":"tang-khong-gian-thu-ba","name":"Tầng không gian thứ ba","cn":"","capDo":"khac","parentId":"vuon-thuoc-trong-di-tich-tien-co","blurb":"Tầng thứ ba của vườn thuốc, còn lại tường ngói và cung điện đổ nát.","detail":"Hoàng Kim thảo sinh trưởng trong một tàn trận tại đây. Phù văn kiếm quang của trận pháp đủ uy hiếp Thiên Thần và suýt chém lìa đầu Thạch Hạo.","theLucLienQuan":[],"nguon":["@c0818"]},{"id":"tang-khong-gian-thu-tu","name":"Tầng không gian thứ tư","cn":"","capDo":"khac","parentId":"vuon-thuoc-trong-di-tich-tien-co","blurb":"Một tầng không gian rộng như sa mạc, phủ đầy cát vàng.","detail":"Nơi này không còn kiến trúc hay cây cỏ thông thường, chỉ có Sa Mạc ngân cắm rễ và hút tinh khí từ mặt đất.","theLucLienQuan":[],"nguon":["@c0818"]},{"id":"tang-khong-gian-thu-nam","name":"Tầng không gian thứ năm","cn":"","capDo":"khac","parentId":"vuon-thuoc-trong-di-tich-tien-co","blurb":"Tầng cuối và nguy hiểm nhất của vườn thuốc Tiên cổ.","detail":"Tầng này còn đôn đá, bàn đá, ngọc sạn, lầu ngọc vỡ nát và một vùng linh thổ vàng kim. Hư Thiên thần đằng bị giam tại một góc bởi trận pháp tương đối hoàn chỉnh có thể giết Thiên Thần.","theLucLienQuan":[],"nguon":["@c0818"]},{"id":"xich-chau","name":"Xích châu","cn":"","capDo":"chau","parentId":"thuong-gioi","blurb":"Châu vực tại Thượng giới, là nơi xuất thân của sơ đại Lạc Đạo.","detail":"Lạc Đạo đến từ Xích châu và từng lập chiến tích giết thần linh khi còn ở cảnh giới Tôn giả.","theLucLienQuan":[],"nguon":["@c0819"]},{"id":"lam-kim-linh","name":"Lam Kim lĩnh","cn":"","capDo":"khac","parentId":"thuong-gioi","blurb":"Nơi phát nguyên của chủng tộc tinh kim thông linh mà Lam Nhất Trần thuộc về.","detail":"Một loại tinh kim tại đây đã thông linh rồi hóa thành hình, trở thành nguồn gốc của Chủng tộc Lam Kim lĩnh.","theLucLienQuan":["Chủng tộc Lam Kim lĩnh"],"nguon":["@c0819"]},{"id":"vuon-hu-thien-than-dang","name":"Vườn Hư Thiên thần đằng","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Vườn thuốc có đại trận bảo vệ, chứa bảo thổ và Hư Thiên thần đằng.","detail":"Tại đây Thạch Hạo cùng Đả Thần Thạch trấn áp Lam Nhất Trần và Lạc Đạo, phá đại trận rồi bắt Hư Thiên thần đằng cùng bảo thổ.","theLucLienQuan":[],"nguon":["@c0820"]},{"id":"vung-sau-tien-co","name":"Vùng sâu Tiên cổ","cn":"","capDo":"vuc","parentId":"tien-co","blurb":"Vùng sâu trong Tiên cổ, nơi nhiều nhân vật mạnh và quái thai cổ đại đã tiến vào.","detail":"Hắc Ám Thần tử và truyền nhân Tiên điện được báo là đã tiến vào nơi này. Tin tức về một sào huyệt do Thập Hung để lại cũng thu hút nhiều người đến tranh đoạt cơ duyên.","theLucLienQuan":["Tiên điện"],"nguon":["@c0820"]},{"id":"sao-huyet-thap-hung","name":"Sào huyệt Thập Hung","cn":"","capDo":"khac","parentId":"vung-sau-tien-co","blurb":"Di tích được cho là do một trong Thập Hung lưu lại tại vùng sâu Tiên cổ.","detail":"Tin tức về sào huyệt đã thu hút rất nhiều người tiến đến tìm kiếm và tranh đoạt cơ duyên.","theLucLienQuan":["Thập Hung"],"nguon":["@c0820"]},{"id":"con-duong-da","name":"Con đường đá","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Con đường đá nơi Thạch Hạo âm thầm trở lại sau khi rời vườn thuốc.","detail":"Thạch Hạo mang theo Đả Thần Thạch và Hoàng điệp trở về đây, ngồi xếp bằng và quyết định bế quan tăng cường thực lực.","theLucLienQuan":[],"nguon":["@c0820"]},{"id":"canh-hoa-tien-dao","name":"Cánh hoa Tiên đạo","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Nơi Thạch Hạo chịu ánh lửa thiêu đốt để vượt ải thành thần. Khi hơn một ngàn ánh lửa hội tụ, cánh hoa che khuất hình ảnh của hắn khỏi ngoại giới.","detail":"Cánh hoa Tiên đạo là địa điểm diễn ra quá trình vượt ải của Thạch Hạo. Sức mạnh tại đây khiến ngoại giới và bia đá không còn quan sát được hắn đúng lúc nguy cơ quỷ biến xuất hiện.","theLucLienQuan":[],"nguon":["@c0822"]},{"id":"ky-nguyen-tien-co-da-bi-diet","name":"Kỷ nguyên Tiên cổ đã bị diệt","cn":"","capDo":"khac","parentId":null,"blurb":"Kỷ nguyên đã diệt vong được Thạch Hạo liên hệ với khu vực con đường đá và các hiện tượng kỳ dị xuất hiện tại đây.","detail":"Mối liên hệ với kỷ nguyên Tiên cổ đã bị diệt khiến Thạch Hạo nhận định khu vực này rất dễ phát sinh những bất trắc chưa thể lý giải.","theLucLienQuan":[],"nguon":["@c0823"]},{"id":"con-duong-da-co","name":"Con đường đá cổ","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Con đường đá cổ là chiến trường nơi Thạch Hạo đối đầu sinh linh quỷ biến.","detail":"Cuộc giao chiến bằng chiến mâu, chiến kích và nhiều thần thông khiến con đường liên tục rung chuyển. Mặt đường dính máu đỏ của Thạch Hạo cùng máu đen có khí tức âm lãnh của đối phương.","theLucLienQuan":[],"nguon":["@c0824"]},{"id":"vuon-thuoc-tien-co-than-bi","name":"Vườn thuốc Tiên cổ thần bí","cn":"","aliases":["Vườn thuốc thần bí"],"capDo":"khac","parentId":"tien-co","blurb":"Vườn thuốc bí ẩn trong Tiên cổ, nơi có nhiều loại thần thảo mang tuổi thọ lâu dài.","detail":"Hư Thiên thần đằng tiết lộ nơi này có Chu quả, Kỳ Lân thụ và Trường Sinh tiên dược.","theLucLienQuan":[],"nguon":["@c0825"]},{"id":"quang-minh-gioi","name":"Quang Minh giới","cn":"","capDo":"gioi-nho","parentId":"tien-co","blurb":"Một tiểu thiên thế giới rộng lớn trong Tiên cổ, nơi tọa lạc Quang Minh thành.","detail":"Thạch Hạo tiến vào Quang Minh giới rồi đi nhiều ngày mới nhìn thấy Quang Minh thành. Khu vực này là một phần trong mạng lưới tiểu thiên thế giới liên thông của Tiên cổ.","theLucLienQuan":["Các phe quái thai cổ đại tại Quang Minh thành","Tiên điện"],"nguon":["@c0826"]},{"id":"quang-minh-thanh","name":"Quang Minh thành","cn":"","capDo":"thanh","parentId":"quang-minh-gioi","blurb":"Một trong mười cổ thánh thành lớn nhất Tiên cổ và là trung tâm giao dịch quan trọng của Quang Minh giới.","detail":"Thành được xây bằng nham thạch vàng, tập trung các sạp trao đổi dược thảo, pháp khí, công pháp, thần liệu và tin tức về mật địa. Giao chiến bị cấm trong thành, còn ân oán phải được giải quyết bên ngoài; dân bản địa cũng tới đây giao dịch với thiên tài ngoại giới.","theLucLienQuan":["Các phe quái thai cổ đại tại Quang Minh thành","Tiên điện"],"nguon":["@c0826"]},{"id":"phu-de-hac-am-than-cung","name":"Phủ đệ Hắc Ám thần cung","cn":"","capDo":"khac","parentId":"quang-minh-thanh","blurb":"Phủ đệ của Hắc Ám thần cung tại Quang Minh thành, chiếm khoảng nửa con phố và bị khói đen bao phủ.","detail":"Không gian trong phủ lạnh lẽo như Minh giới. Ngay sân đầu tiên có một truyền tống trận nối tới thung lũng đặt sát trường Minh tộc.","theLucLienQuan":["Hắc Ám thần cung","Minh tộc"],"nguon":["@c0827"]},{"id":"thung-lung-sat-truong-minh-toc","name":"Thung lũng sát trường Minh tộc","cn":"","capDo":"khac","parentId":"quang-minh-gioi","blurb":"Thung lũng lớn ngoài Quang Minh thành, là đầu kia của truyền tống trận đặt trong Hắc Ám thần cung.","detail":"Minh tộc bố trí một sát trường tràn ngập sương đen và sát khí tại đây để phục kích Thạch Hạo.","theLucLienQuan":["Minh tộc","Hắc Ám thần cung"],"nguon":["@c0827"]},{"id":"phu-de-long-cung","name":"Phủ đệ Long cung","cn":"","capDo":"khac","parentId":"quang-minh-thanh","blurb":"Phủ đệ màu xanh nước biển của Long nữ tại Quang Minh thành.","detail":"Kiến trúc tỏa ánh sáng dịu và do những người đi theo Long nữ quản lý. Nơi đây được dùng để thu thập bảo dược dù Long nữ chưa từng trực tiếp xuất hiện.","theLucLienQuan":["Long cung"],"nguon":["@c0827"]},{"id":"cung-dien-tien-dien-tai-quang-minh-thanh","name":"Cung điện Tiên điện tại Quang Minh thành","cn":"","capDo":"khac","parentId":"quang-minh-thanh","blurb":"Quần thể cung điện hùng vĩ của Tiên điện tại Quang Minh thành.","detail":"Chủ điện được đúc bằng đồng, còn phần lớn kiến trúc là di tích do các đời tu sĩ lưu lại. Đây là nơi Thạch Hạo công khai chất vấn Tiên điện và đánh Hạc vàng.","theLucLienQuan":["Tiên điện"],"nguon":["@c0827"]},{"id":"bien-gioi-khu-vuc-khong-nguoi","name":"Biên giới khu vực không người","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực nơi người ngoài Tiên cổ và các giáo chủ tập trung chờ những quái thai cổ đại xuất quan.","detail":"Các giáo chủ tại đây dùng pháp lực khắc tên tu sĩ lên cánh hoa Tiên đạo để dò xét tình trạng của họ, nhưng nhiều người đang bế quan được đại đạo và sương mù che giấu.","theLucLienQuan":["Các Giáo chủ thượng giới"],"nguon":["@c0827"]},{"id":"day-nui-ngoai-quang-minh-thanh","name":"Dãy núi ngoài Quang Minh thành","cn":"","capDo":"khac","parentId":"quang-minh-gioi","blurb":"Dãy núi ngoài Quang Minh thành trở thành chiến trường giữa Thạch Hạo và lực lượng Tiên điện.","detail":"Hai Tiên tướng dùng Phá Không phù đưa Thạch Hạo tới đây để vây giết. Sau trận chiến, núi sụp, đất lún, hai Tiên tướng cùng hơn mười cường giả tử trận và chỉ Hạc vàng còn sống trong trạng thái hoảng loạn.","theLucLienQuan":["Tiên điện"],"nguon":["@c0828"]},{"id":"mo-quang-kim-loai","name":"Mỏ quặng kim loại","cn":"","capDo":"khac","parentId":null,"blurb":"Một mỏ quặng nơi Lam Nhất Trần bị nhóm người chưa rõ danh tính vây chặn.","detail":"Lam Nhất Trần mang theo Bát Trân Kỳ nhưng không thể thoát khỏi vòng vây tại đây, khiến Lạc Đạo phải tìm Thạch Hạo cầu viện.","theLucLienQuan":[],"nguon":["@c0828"]},{"id":"ngan-ma-son","name":"Ngân Ma sơn","cn":"","capDo":"vuc","parentId":"quang-minh-gioi","blurb":"Dãy núi kim loại trắng sáng, lấy ngân tinh làm chủ và nằm trong Quang Minh giới.","detail":"Lam Nhất Trần lợi dụng thiên phú hòa vào kim loại để ẩn náu tại đây cùng Bát Trân Kỳ. Ngọn núi trung tâm có hình cối xay, bị nhiều thế lực bố trí đại trận bao vây và thu hẹp phạm vi truy bắt.","theLucLienQuan":["Hỏa Vân động","Hắc Ám thần cung","Kiếm cốc","Minh tộc"],"nguon":["@c0829"]},{"id":"ngan-linh-son","name":"Ngân Linh sơn","cn":"","capDo":"khac","parentId":"quang-minh-gioi","blurb":"Một ngọn núi có linh tuyền thơm và trong veo chảy ra sau khi đại trận được phá giải gần hết.","detail":"Lộ Dịch tìm thấy dòng linh tuyền dưới chân Ngân Linh sơn. Nước suối sau đó được đưa vào đỉnh để nấu huyết nhục sơ đại.","theLucLienQuan":[],"nguon":["@c0832"]},{"id":"kim-loai-son","name":"Kim Loại sơn","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Ngọn núi nơi Lam Nhất Trần từng bế quan và bắt được Bát Trân Kỳ.","detail":"Trong thời gian bế quan tại đây, Lam Nhất Trần vô tình tiến vào lòng đất và phát hiện Bát Trân Kỳ, một kỳ trân rất khó tìm thấy từ mặt đất.","theLucLienQuan":[],"nguon":["@c0833"]},{"id":"dong-co-hon-don-cua-ninh-xuyen","name":"Động cổ hỗn độn của Ninh Xuyên","cn":"","capDo":"khac","parentId":null,"blurb":"Bảo địa có dị tượng hỗn độn, nơi Ninh Xuyên bế quan và dung hợp khúc xương cánh tay cổ.","detail":"Ninh Xuyên rời động để điều chỉnh trạng thái rồi quay lại tiến hành dung hợp. Thiên cơ tại nơi này che khuất quá trình lột xác của hắn khỏi sự quan sát của ngoại giới.","theLucLienQuan":[],"nguon":["@c0834"]},{"id":"phu-de-luc-quan-vuong","name":"Phủ đệ Lục Quan vương","cn":"","capDo":"khac","parentId":"quang-minh-thanh","blurb":"Căn cứ của Ninh Xuyên tại Quang Minh thành, có khôi lỗi mang chiến lực Chân Thần trấn giữ.","detail":"Phủ đệ chứa một bảo khố lớn với linh dược, mười một cây thánh dược, năm bán thần quả và nhiều tài nguyên khác. Thạch Hạo cùng Lạc Đạo và Lam Nhất Trần đánh vào nơi này, phá khôi lỗi canh giữ rồi lấy sạch tài vật.","theLucLienQuan":[],"nguon":["@c0834"]},{"id":"sao-huyet-nghi-cua-thap-hung","name":"Sào huyệt nghi của Thập Hung","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực giống một tổ kiến, bị nghi là nơi bế quan của sinh linh có sức mạnh thân thể lớn nhất trong Thập Hung thái cổ.","detail":"Nhiều người từng cảm nhận được khí tức thần dược tại đây nhưng không tìm thấy nguồn, thậm chí có người bỏ mạng. Vì cần tài nguyên cho con đường tu luyện chưa từng có, Thạch Hạo quyết định tới thăm dò nơi này với hy vọng tìm được thần dược hoặc Trường Sinh dược.","theLucLienQuan":["Thập Hung"],"nguon":["@c0834"]},{"id":"sao-gioi","name":"Sào giới","cn":"","capDo":"gioi-nho","parentId":"tien-co","blurb":"Một tiểu thiên thế giới rộng lớn nằm rất xa Quang Minh giới, mang tên theo sào huyệt của một trong Thập Hung.","detail":"Sào giới phần lớn được bao phủ bởi rừng nguyên thủy, nơi tồn tại nhiều độc trùng, mãnh thú và sinh linh cổ có cảnh giới cao. Hành trình tới Hung sào phải vượt qua hàng loạt hiểm địa và những quy tắc không gian kỳ dị.","theLucLienQuan":["Thập Hung"],"nguon":["@c0835"]},{"id":"khu-vuc-ria-sao-huyet-thap-hung","name":"Khu vực rìa sào huyệt Thập Hung","cn":"","capDo":"khac","parentId":"sao-gioi","blurb":"Vùng bên ngoài sào huyệt Thập Hung, vừa nguy hiểm chết người vừa chứa nhiều tạo hóa lớn.","detail":"Khoảng tám vạn đến mười vạn người đã tử vong tại khu vực này. Dù vậy, đông đảo tu sĩ vẫn tìm đến vì những vận may có thể đạt được quanh sào huyệt.","theLucLienQuan":["Thập Hung"],"nguon":["@c0835"]},{"id":"quy-lam","name":"Quỷ lâm","cn":"","capDo":"khac","parentId":"sao-gioi","blurb":"Khu rừng rộng không dưới vạn dặm nằm trên đường dẫn tới Hung sào.","detail":"Quỷ lâm chứa sức mạnh kỳ dị có thể khiến người xâm nhập lạc hướng, rung chuyển nguyên thần và dần quên mất bản thân. Lộ Dịch từng bị ảnh hưởng đến mức suýt quên tên mình khi đi qua nơi đây.","theLucLienQuan":[],"nguon":["@c0835"]},{"id":"hung-sao","name":"Hung sào","cn":"","capDo":"khac","parentId":"sao-gioi","blurb":"Sào huyệt của một trong Thập Hung, nằm giữa dãy núi đổ sụp và được hỗn độn bao phủ.","detail":"Hung sào được đào rỗng trong một dãy núi, tỏa ra khí hỗn độn và khí tức đại đạo. Nhiều thần thổ, ma địa và thánh cảnh mang quy tắc không gian chồng lớp bao quanh khiến sào huyệt trông gần nhưng thực tế vẫn ở rất xa; chưa ai có thể tiến vào nơi sâu nhất.","theLucLienQuan":["Thập Hung"],"nguon":["@c0835"]},{"id":"vung-dat-tao-hoa-co-ho-linh-dich","name":"Vùng đất tạo hóa có hồ Linh dịch","cn":"","capDo":"khac","parentId":"hung-sao","blurb":"Một vùng tạo hóa quanh Hung sào, nơi linh khí ngưng tụ thành hồ Linh dịch.","detail":"Trong hồ có Phượng ngư mang bản nguyên sinh mệnh. Loài cá này được cho là có khả năng kéo dài tuổi thọ, khiến vùng đất trở thành mục tiêu thăm dò đáng giá.","theLucLienQuan":[],"nguon":["@c0835"]},{"id":"khu-vuc-than-qua-thu","name":"Khu vực Thần Quả thụ","cn":"","capDo":"khac","parentId":"hung-sao","blurb":"Địa vực quanh Hung sào có một cây cổ thụ mang khí tức Thần đạo và kết thần quả.","detail":"Thần Quả thụ mọc trong một vùng tạo hóa được ngăn cách bởi kết cấu không gian kỳ dị. Khi nhóm Thạch Hạo quan sát nơi này, đã có tu sĩ tìm cách tiếp cận cổ thụ để hái quả.","theLucLienQuan":[],"nguon":["@c0835"]},{"id":"thanh-canh-dong-song-sinh-menh","name":"Thánh cảnh dòng sông sinh mệnh","cn":"","capDo":"khac","parentId":"hung-sao","blurb":"Một thánh cảnh quanh Hung sào có cung điện cổ trôi trên dòng sông sinh mệnh.","detail":"Cung điện cổ phát ra đạo âm và những phù văn giống như đang tụng kinh. Đây là một trong nhiều vùng tạo hóa bị các lớp không gian kỳ dị ngăn cách quanh Hung sào.","theLucLienQuan":[],"nguon":["@c0835"]},{"id":"cac-khu-vuc-bi-canh-do-co-lo-ket-noi","name":"Các khu vực bí cảnh do cổ lộ kết nối","cn":"","capDo":"gioi-nho","parentId":"tien-co","blurb":"Quần thể địa vực được cổ lộ phát sáng kết nối và cưỡng chế đưa người tham dự tới những điểm khác nhau.","detail":"Mỗi khu vực rộng gần bằng một tiểu thiên thế giới, có linh khí dồi dào đến mức tinh khí trong hư không có thể ngưng thành linh dịch. Linh dược mọc dày đặc, nhưng nơi đây cũng diễn ra nhiều cuộc tàn sát và tranh cướp thiên tài địa bảo.","theLucLienQuan":[],"nguon":["@c0836"]},{"id":"hang-co-cua-thieu-nien-song-cot","name":"Hang cổ của thiếu niên song cốt","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Nơi thiếu niên song cốt của Tần tộc bế quan trước khi lên đường tìm sào huyệt Thập Hung.","detail":"Tiên quang, phù văn và kinh văn Chí tôn hiện lên tại hang cổ khi thiếu niên xuất quan.","theLucLienQuan":["Tần tộc"],"nguon":["@c0836"]},{"id":"ngon-nui-den-phu-khi-hon-don","name":"Ngọn núi đen phủ khí hỗn độn","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Một tuyệt địa nằm trong tiểu thiên thế giới, được khí hỗn độn bao phủ.","detail":"Thạch Nghị ngủ đông và bế quan tại đây nhiều năm trước khi thức tỉnh thần năng Trùng đồng và tái hiện nhân gian.","theLucLienQuan":[],"nguon":["@c0836"]},{"id":"dong-phu-cua-ninh-xuyen","name":"Động phủ của Ninh Xuyên","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Nơi Lục Quan vương Ninh Xuyên bế quan và điều chỉnh trạng thái.","detail":"Ninh Xuyên rời động phủ này để hướng tới Hung sào và tuyên bố sẽ truy sát đời sau tội huyết.","theLucLienQuan":[],"nguon":["@c0836"]},{"id":"khu-vuc-ben-ngoai-thap-hung-sao","name":"Khu vực bên ngoài Thập Hung sào","cn":"","capDo":"vuc","parentId":"sao-gioi","blurb":"Vùng núi rừng bên ngoài khu vực thần bí của Thập Hung sào, nơi tồn tại lượng lớn thần thi và hài cốt.","detail":"Vùng này bị quy tắc cấm không hạn chế phi hành. Càng đi sâu, nhóm Thạch Hạo càng gặp nhiều thi thể thối rữa, bao gồm cả sơ đại và Chân Thần, trước khi tiến tới cốt địa.","theLucLienQuan":["Thập Hung"],"nguon":["@c0837"]},{"id":"cot-dia","name":"Cốt địa","cn":"","capDo":"khac","parentId":"khu-vuc-ben-ngoai-thap-hung-sao","blurb":"Vùng đất trắng được hình thành từ vô số bạch cốt tích lũy và phong hóa qua thời gian dài.","detail":"Cốt địa có âm khí nặng và chứa hơn hai vạn bộ hài cốt mà nhóm Thạch Hạo nhìn thấy trên đường. Một quy tắc khó hiểu tại đây từ từ làm huyết nhục của sinh linh tiêu biến, còn cuối vùng đất là đại trận cổ bảo vệ khu rừng Thần Quả.","theLucLienQuan":[],"nguon":["@c0837"]},{"id":"khu-rung-than-qua","name":"Khu rừng Thần Quả","cn":"","capDo":"khac","parentId":"cot-dia","blurb":"Vùng đất bí mật tràn ngập thánh quang và sinh cơ, nằm sau đại trận cổ ở cuối cốt địa.","detail":"Khu rừng hoàn toàn tương phản với ma thổ chất đầy thi hài bên ngoài. Nơi đây có hàng chục Thần Quả thụ cùng sinh trưởng, trên cây mang những quả hình người nhiều màu và tỏa hương thơm.","theLucLienQuan":[],"nguon":["@c0837"]},{"id":"rung-ban-tham-qua-thu","name":"Rừng Bán Tham quả thụ","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Khu cổ địa có nhiều Bán Tham quả thụ, tràn ngập thần hà và hương thơm nhưng ẩn chứa sát cơ.","detail":"Nơi sinh sống của vô số Hắc Thần trùng và Quỷ Quái thần, với các cá thể trải rộng từ Tôn Giả đến Thiên Thần cảnh. Thần hà và hương thơm trong rừng đem lại cảm giác gần như phạt mao tẩy tủy, song các thần thụ đồng thời được đàn Hắc Thần trùng bảo vệ nghiêm ngặt.","theLucLienQuan":[],"nguon":["@c0838"]},{"id":"vung-dat-bach-cot","name":"Vùng đất bạch cốt","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Một địa hình phủ đầy bạch cốt trên đường nhóm Thạch Hạo chạy khỏi đàn Hắc Thần trùng.","detail":"Nhóm Thạch Hạo vượt qua vùng đất này trong cuộc tháo chạy khỏi đại quân Hắc Thần trùng và hai cá thể cấp Thiên Thần.","theLucLienQuan":[],"nguon":["@c0839"]},{"id":"suon-nui-mau-mau","name":"Sườn núi màu máu","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Một sườn núi nằm sau vùng đất bạch cốt trên tuyến đường chạy khỏi đàn sâu.","detail":"Khi nhóm Thạch Hạo vượt qua sườn núi này, số lượng Hắc Thần trùng truy sát phía sau vẫn tiếp tục gia tăng.","theLucLienQuan":[],"nguon":["@c0839"]},{"id":"van-tien-linh","name":"Vẫn Tiên lĩnh","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Dãy núi đỏ sậm nằm trên con đường bắt buộc dẫn vào Hung sào.","detail":"Tương truyền một vị tiên đã chết tại đây hơn một kỷ nguyên trước, khiến tiên huyết nhuộm đỏ núi. Phần tinh hoa của tiên huyết có thể đã bị Hung sào hấp thu.","theLucLienQuan":[],"nguon":["@c0840"]},{"id":"khu-rung-than-thu","name":"Khu rừng Thần thụ","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Khu vực nguy hiểm nơi nhóm Thạch Hạo hái được thần quả trước khi tiến về Hung sào.","detail":"Trong rừng có bầy Hắc Thần trùng, hàng vạn thi thể và một loại tàn dược có khả năng bức lui bầy sâu. Nhóm Thạch Hạo rời khỏi nơi này sau khi chia thần quả.","theLucLienQuan":[],"nguon":["@c0840"]},{"id":"co-dien-tren-dong-song-sinh-menh","name":"Cổ điện trên dòng sông sinh mệnh","cn":"","capDo":"khac","parentId":"thanh-canh-dong-song-sinh-menh","blurb":"Cung điện cổ bí ẩn từng xuất hiện trên dòng sông sinh mệnh.","detail":"Cổ điện có tiếng tụng kinh và ký hiệu đại đạo bao quanh. Nhóm Thạch Hạo tìm kiếm trong nhiều ngày nhưng không thể gặp lại nó.","theLucLienQuan":[],"nguon":["@c0840"]},{"id":"vung-huyet-nhat-huyet-nguyet-va-tinh-tu","name":"Vùng huyết nhật, huyết nguyệt và tinh tú","cn":"","capDo":"khac","parentId":"hung-sao","blurb":"Không gian trên các đỉnh núi có mười huyết nhật, ba mươi ba huyết nguyệt và ba ngàn ngôi sao đã bị luyện hóa.","detail":"Huyết dịch thần thánh có thể khiến một huyết nguyệt chấn động, dẫn ánh sáng xuống dưới và mở ra con đường cổ tiến sâu vào Hung sào.","theLucLienQuan":["Thạch tộc"],"nguon":["@c0848"]},{"id":"ba-canh-cua-do-sam","name":"Ba cánh cửa đỏ sậm","cn":"","capDo":"khac","parentId":"hung-sao","blurb":"Ba lối vào nằm cuối con đường cổ dưới lòng đất trong Hung sào.","detail":"Thạch Nghị chọn cửa thứ nhất, Tần Hạo chọn cửa thứ hai, còn Thạch Hạo dẫn Lộ Dịch, Lạc Đạo và Lam Nhất Trần tiến vào cửa thứ ba.","theLucLienQuan":["Thạch tộc"],"nguon":["@c0848"]},{"id":"bien-dung-nham","name":"Biển dung nham","cn":"","capDo":"khac","parentId":"hung-sao","blurb":"Biển dung nham đỏ sậm chứa cổ hỏa có thể thiêu đốt thần linh.","detail":"Thánh dược mọc giữa dung nham và được phù văn bảo vệ. Đoàn Thạch Hạo phải dùng một thánh quả đổi lấy sự trợ giúp của cốt giao để sang bờ đối diện.","theLucLienQuan":[],"nguon":["@c0848"]},{"id":"rung-da-kiem-ngan","name":"Rừng đá kiếm ngân","cn":"","capDo":"khac","parentId":"hung-sao","blurb":"Khu rừng đá lổm chổm nằm ở bờ bên kia biển dung nham.","detail":"Những vết kiếm trên đá tỏa ra sát ý, biến nơi đây thành một cửa ải mà đoàn Thạch Hạo phải phá giải.","theLucLienQuan":[],"nguon":["@c0848"]},{"id":"diem-cuoi-tuyen-tranh-da","name":"Điểm cuối tuyến tranh đá","cn":"","capDo":"khac","parentId":"hung-sao","blurb":"Khu vực gần cuối lộ tuyến có bồ đoàn tỏa khí hỗn độn và nhiều thi hài cường giả.","detail":"Tuyệt bút bên một thi hài xác nhận người chết là Bành Thiên Ý của Thần Dực tộc. Sự hiện diện của nhiều hài cốt siêu phàm cho thấy khu vực này đặc biệt nguy hiểm.","theLucLienQuan":["Thần Dực tộc"],"nguon":["@c0848"]},{"id":"tu-lo-trong-hung-sao","name":"Tử lộ trong Hung sào","cn":"","capDo":"khac","parentId":"hung-sao","blurb":"Con đường chết chóc trong Hung sào có bồ đoàn chứa cổ kinh làm cửa ải cuối. Người ngộ pháp phải vượt qua công kích nguyên thần mạnh hơn chính mình.","detail":"Tử lộ lưu giữ năm bộ di cốt hoàn chỉnh của những kỳ tài đã chết không rõ nguyên do. Tại cửa ải cuối, bồ đoàn truyền kinh văn về sức mạnh, phong kín đường lui và phát động lưỡi đao ánh sáng chuyên chém nguyên thần; vượt qua thử thách sẽ mở được cửa vào động phủ trung tâm.","theLucLienQuan":[],"nguon":["@c0849"]},{"id":"dong-phu-tram-cua-da","name":"Động phủ trăm cửa đá","cn":"","capDo":"gioi-nho","parentId":"hung-sao","blurb":"Không gian trung tâm có một trăm cửa đá hội tụ, nơi nhóm Thạch Hạo được truyền tống tới sau khi vượt tử lộ.","detail":"Động phủ rộng lớn có một trăm cửa đá và nhiều đạo đài với các sinh linh đang ngồi xếp bằng. Cửa nhóm Thạch Hạo vừa vượt qua cùng chín cửa khác đều khắc chữ Tử, cho thấy chỉ mười trong số một trăm lối vào bị xem là tử lộ.","theLucLienQuan":[],"nguon":["@c0849"]},{"id":"co-dong-sau-trong-dong-phu","name":"Cổ động sâu trong động phủ","cn":"","capDo":"khac","parentId":"dong-phu-tram-cua-da","blurb":"Cổ động mờ ảo nằm ở nơi sâu nhất của động phủ trăm cửa đá, có khí hỗn độn và tiên quang lưu chuyển.","detail":"Bên trong cổ động đặt một bàn ngọc, trên đó có cốt thư thần thánh đang tỏa tiên quang. Nhóm Thạch Hạo mới nhìn thấy nơi này từ xa và chưa tiếp cận cốt thư.","theLucLienQuan":[],"nguon":["@c0849"]},{"id":"tien-dong","name":"Tiên động","cn":"","capDo":"khac","parentId":"dong-phu-dao-dai","blurb":"Động cổ được màn sáng do khí hỗn độn và tiên quang tạo thành bảo vệ. Bên trong chứa bảy tấm cốt thư thần thánh, thần dược, pháp khí và nhiều bảo vật quý hiếm.","detail":"Tiên động có pháp tắc không gian khiến bàn đá ngọc bên trong hiện ra cao như núi. Cấm chế bảo vệ động phủ có thể giam cầm khu vực, hạn chế phi hành và kéo người đang giao chiến xuống mặt đất.","theLucLienQuan":[],"nguon":["@c0850"]},{"id":"dong-phu-dao-dai","name":"Động phủ đạo đài","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực bên ngoài tiên động có gần hai trăm cao thủ tụ tập trên nhiều dãy đạo đài. Áp lực tăng mạnh khi tiến gần động cổ, còn đứng trên đạo đài có thể giảm bớt sự áp chế.","detail":"Các đạo đài cho phép người tu luyện dùng chân huyết đổi lấy từng câu kinh văn truyền ra từ cốt thư trong tiên động. Nhiều con đường nguy hiểm, gồm cả cửa Tử, dẫn tới khu vực này.","theLucLienQuan":[],"nguon":["@c0850"]},{"id":"ba-muoi-sau-dao-dai-hang-dau","name":"Ba mươi sáu đạo đài hàng đầu","cn":"","capDo":"khac","parentId":"dong-phu-dao-dai","blurb":"Hàng ba mươi sáu đạo đài nằm gần tiên động nhất và chịu áp lực đủ nghiền nát Thần linh cùng Chân Thần bình thường. Ban đầu có hai mươi cao thủ chiếm giữ nơi này.","detail":"Bên dưới hàng đạo đài chất hàng trăm bộ hài cốt của các thiên tài từ nhiều đời trước. Thạch Hạo chiếm đạo đài thứ hai mươi mốt, còn Long Nữ ngồi tại đạo đài thứ hai mươi hai.","theLucLienQuan":[],"nguon":["@c0850"]},{"id":"ban-ngoc-trong-tien-dong","name":"Bàn ngọc","cn":"","capDo":"khac","parentId":"tien-dong","blurb":"Bàn ngọc khổng lồ cao hơn núi lớn, có bốn chân như cột chống trời và đặt bảo cốt được cho là chứa bảo thuật Thập Hung.","detail":"Áp lực trong tiên động khiến các cường giả khó tiếp cận bàn ngọc. Thanh niên tóc trắng dùng bí bảo Thiên Thần xông lên, nhưng vừa bắt lấy bảo cốt phía trên thì bị hút huyết dịch và kích hoạt sát cục.","theLucLienQuan":[],"nguon":["@c0851"]},{"id":"vach-da-trong-tien-dong","name":"Vách đá trong tiên động","cn":"","capDo":"khac","parentId":"tien-dong","blurb":"Vách đá bí ẩn nơi cây thần dược và Ốc biển Thiên Văn lần lượt chui vào rồi biến mất.","detail":"Thạch Hạo cùng những người khác từng công kích vách đá sau khi cây thần dược biến mất, nhưng bề mặt không xuất hiện ngay cả một vết trầy. Ốc biển Thiên Văn sau đó cũng tiến vào cùng vách đá và mất dấu.","theLucLienQuan":[],"nguon":["@c0851"]},{"id":"cac-toa-dao-dai-ngoai-tien-dong","name":"Các tòa đạo đài ngoài tiên động","cn":"","capDo":"khac","parentId":"tien-dong","blurb":"Các đạo đài giữ những người chưa thể tiến vào tiên động trong lúc áp lực còn tồn tại.","detail":"Khi áp lực đột ngột biến mất, đông đảo cường giả từ các đạo đài tràn vào tranh bảo. Sau khi sát cục bùng phát, Thạch Hạo và Long Nữ chạy ngược về phía các đạo đài để thoát thân.","theLucLienQuan":[],"nguon":["@c0851"]},{"id":"ban-da-ngoc-cao-hon-nui","name":"Bàn đá ngọc cao hơn núi","cn":"","capDo":"khac","parentId":"hung-sao","blurb":"Bàn đá ngọc khổng lồ trong Hung sào, nơi thanh niên tóc trắng bị cốt thư hút sạch bảo huyết.","detail":"Cốt thư trên bàn đá ngọc phá hủy pháp khí hộ thể của thanh niên tóc trắng, khiến hắn tử vong rồi kích hoạt sát trường trong động cổ.","theLucLienQuan":[],"nguon":["@c0852"]},{"id":"dao-dai-hut-mau","name":"Đạo đài hút máu","cn":"","capDo":"khac","parentId":"hung-sao","blurb":"Đạo đài trong Hung sào trói buộc và hút khô những người không kịp rời đi.","detail":"Ngoài huyết dịch, đạo đài còn rút cả ký hiệu và cốt văn trong cơ thể nạn nhân, sau đó dẫn chúng về một phương chưa rõ.","theLucLienQuan":[],"nguon":["@c0852"]},{"id":"chien-truong-co-duoi-long-dat","name":"Chiến trường cổ dưới lòng đất","cn":"","capDo":"khac","parentId":"hung-sao","blurb":"Chiến trường cổ nằm sau bức vách trận pháp do Thạch Hạo phá vỡ.","detail":"Nơi đây có mặt đất nâu xám và xương trắng rải khắp. Thạch Hạo tìm thấy Tần Hạo đang bị thương tại chiến trường này.","theLucLienQuan":[],"nguon":["@c0852"]},{"id":"dao-duoc-lieu-trong-hu-khong","name":"Đảo dược liệu trong hư không","cn":"","capDo":"khac","parentId":"chien-truong-co-duoi-long-dat","blurb":"Hòn đảo lơ lửng chứa nhiều thánh dược và thần dược, nối với mặt đất bằng cầu thang ngọc.","detail":"Trận pháp thần bí bảo vệ đảo đã giết hơn nghìn cao thủ tìm cách tiến lên. Tần Hạo sống sót sau thảm sát nhờ chiến y Trường Sinh và một bí bảo thế mạng.","theLucLienQuan":[],"nguon":["@c0852"]},{"id":"canh-cua-co-hon-don","name":"Cánh cửa cổ hỗn độn","cn":"","capDo":"khac","parentId":"hung-sao","blurb":"Cánh cửa cổ bao phủ bởi ánh sáng hỗn độn, được quần hùng xem là sinh lộ khỏi Hung sào.","detail":"Sát lực quanh cửa nghiền nát phần lớn người đến gần. Nhóm Thạch Hạo phải sử dụng nhiều bí bảo mạnh nhất để cưỡng ép vượt qua, nhưng chỉ hơn mười người sống sót.","theLucLienQuan":[],"nguon":["@c0852"]},{"id":"khu-co-dia-quanh-hung-sao","name":"Khu cổ địa quanh Hung sào","cn":"","capDo":"khac","parentId":"hung-sao","blurb":"Khu vực kỳ lạ quanh Hung sào, nơi các phương thức vượt hư không bị hạn chế.","detail":"Phá Không phù không thể giúp người sử dụng vượt qua hư không tại đây. Nhóm Thạch Hạo phải chiến đấu xuyên qua trùng triều và chạy tới ranh giới cuối khu vực mới thoát được truy sát.","theLucLienQuan":[],"nguon":["@c0854"]},{"id":"van-gioi","name":"Vân giới","cn":"","capDo":"gioi-nho","parentId":"tien-co","blurb":"Một tiểu thiên thế giới trong Tiên cổ, nơi nhóm Thạch Hạo phát tán chân dung người bí ẩn và chờ tin tức.","detail":"Thạch Hạo, Trường Cung Diễn và Long Nữ tới một tòa thành lớn tại Vân giới. Long Nữ cho in chân dung chàng trai thần bí lên tường thành, khắc thông báo và huy động mạng lưới Long cung treo thưởng tìm kiếm lai lịch của hắn.","theLucLienQuan":["Long cung"],"nguon":["@c0855"]},{"id":"thanh-thanh-linh","name":"Thành Thanh Linh","cn":"","capDo":"thanh","parentId":"thanh-linh-gioi","blurb":"Thành trì lớn dài hơn trăm dặm trong Thanh Linh giới, kết hợp khu phố phồn hoa với cổ thụ và núi rừng.","detail":"Thành Thanh Linh có các khu giao dịch thánh dược và kỳ trân, đồng thời bao bọc nhiều cổ thụ, núi rừng cùng những đường đá dẫn vào các khu vực thanh tĩnh.","theLucLienQuan":[],"nguon":["@c0856"]},{"id":"thanh-linh-gioi","name":"Thanh Linh giới","cn":"","capDo":"gioi-nho","parentId":"tien-co","blurb":"Một tiểu thiên thế giới thuộc Tiên cổ, nổi bật bởi thảm thực vật um tùm và nhiều dược thảo.","detail":"Thanh Linh giới có nhiều cây cỏ và dược liệu, nhưng lượng thánh dược có thể thu hái đã suy giảm sau thời gian dài bị các tu sĩ khai thác.","theLucLienQuan":[],"nguon":["@c0856"]},{"id":"vuon-hoa-dao-thanh-linh","name":"Vườn hoa đào","cn":"","capDo":"khac","parentId":"thanh-thanh-linh","blurb":"Tịnh thổ nằm trong khu vực phồn hoa của thành Thanh Linh, tập trung nhiều quán trà, quán rượu và nhà hàng.","detail":"Vườn hoa đào có những cây đào mang linh tính, đồng thời nở hoa và kết quả. Các cơ sở ăn uống nằm xen giữa rừng đào, trong đó Bát Trân lâu tọa lạc ở khu vực sâu bên trong.","theLucLienQuan":[],"nguon":["@c0856"]},{"id":"bat-tran-lau","name":"Bát Trân lâu","cn":"","capDo":"khac","parentId":"vuon-hoa-dao-thanh-linh","blurb":"Tửu lâu lớn nằm sâu trong vườn hoa đào, chuyên bán rượu thánh dược và Bát Trân thái cổ.","detail":"Bát Trân lâu là nơi sơ đại và cường giả các châu tụ họp, giao lưu cùng trao đổi vật phẩm. Tại đây có bán rượu thánh dược, Bát Trân Lý và Bát Trân Phượng với giá rất cao.","theLucLienQuan":["Tiên điện","Minh tộc"],"nguon":["@c0856"]},{"id":"dam-lay-te-dan","name":"Đầm lầy tế đàn","cn":"","capDo":"khac","parentId":"thanh-linh-gioi","blurb":"Đầm lầy âm u, hôi thối và quanh năm thiếu ánh mặt trời tại Thanh Linh giới.","detail":"Bên trong đầm lầy có một tế đàn nhỏ xây bằng vật liệu màu đỏ, do chiến tướng thứ ba của Tiên điện canh giữ để truyền cốt thư tới nơi truyền nhân bế quan.","theLucLienQuan":["Tiên điện"],"nguon":["@c0859"]},{"id":"tieu-thien-the-gioi-sa-mac-vang","name":"Tiểu thiên thế giới sa mạc vàng","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Tiểu thiên thế giới không rõ tên mà nhóm Thạch Hạo tới sau khi tọa độ truyền tống bị sai lệch.","detail":"Phần lớn bề mặt là cát vàng, không có sinh linh hay cây cỏ. Nhóm Thạch Hạo tìm kiếm trong phạm vi trăm dặm rồi phát hiện một đảo xanh biệt lập.","theLucLienQuan":["Tiên điện"],"nguon":["@c0859"]},{"id":"dao-xanh-trong-sa-mac","name":"Đảo xanh trong sa mạc","cn":"","capDo":"khac","parentId":"tieu-thien-the-gioi-sa-mac-vang","blurb":"Hòn đảo biệt lập chưa tới ngàn trượng nổi bật giữa vùng cát vàng.","detail":"Trên đảo có cây cỏ sáng như ngọc, sương trắng và khí hỗn độn. Trung tâm đảo là một ngọn núi đá chứa động cổ, được trận pháp bao quanh.","theLucLienQuan":["Tiên điện"],"nguon":["@c0859"]},{"id":"dong-co-hon-don","name":"Động cổ hỗn độn","cn":"","capDo":"khac","parentId":"dao-xanh-trong-sa-mac","blurb":"Động cổ nằm trong núi đá giữa đảo xanh, có sương trắng và khí hỗn độn bao phủ.","detail":"Long Huyết tổ ngạc bế quan trong động và giao chiến với Thạch Hạo tại đây. Sau khi đánh bại chiến tướng thứ nhất, Thạch Hạo hướng vào sâu trong động gọi truyền nhân Tiên điện ra ứng chiến.","theLucLienQuan":["Tiên điện"],"nguon":["@c0859"]},{"id":"hon-dao-biet-lap","name":"Hòn đảo biệt lập","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Hòn đảo nơi Thạch Hạo vừa giao chiến với Long Huyết tổ ngạc.","detail":"Mặt đảo bị rạn nứt và cây cỏ mất hơn phân nửa sau trận chiến. Ngọn núi đá chứa động cổ vẫn nguyên vẹn nhờ trận pháp phòng hộ.","theLucLienQuan":["Tiên điện"],"nguon":["@c0860"]},{"id":"dong-co-tren-dao","name":"Động cổ trên đảo","cn":"","capDo":"khac","parentId":"hon-dao-biet-lap","blurb":"Động thần được trận pháp bảo vệ, nằm gần bí cảnh nơi truyền nhân Tiên điện bế quan.","detail":"Bên trong động cổ có tế đàn trung chuyển màu vàng nhạt, kho thần liệu, thánh dược, bán thần dược và Vật liệu mật đá. Đây là một cứ điểm thu gom tài nguyên cho truyền nhân Tiên điện.","theLucLienQuan":["Tiên điện"],"nguon":["@c0860"]},{"id":"bi-canh-ke-tiep","name":"Bí cảnh kế tiếp","cn":"","capDo":"gioi-nho","parentId":"tien-co","blurb":"Điểm đến chưa rõ tên của tế đàn màu vàng nhạt trong động cổ.","detail":"Thạch Hạo dự đoán bí cảnh này nằm rất gần nơi truyền nhân Tiên điện bế quan và có thể là điểm chạm trán kế tiếp nếu không xảy ra biến cố.","theLucLienQuan":["Tiên điện"],"nguon":["@c0860"]},{"id":"son-mach-doc-trung","name":"Sơn mạch độc trùng","cn":"","capDo":"vuc","parentId":"tien-co","blurb":"Tuyệt địa phủ khói độc và vô số độc trùng thành tinh, bao gồm cả thần trùng có thể giết cường giả Thần Hỏa.","detail":"Khói độc trong sơn mạch có khả năng ăn mòn thần lực. Rắn rết, bò cạp, nhện và nhiều độc trùng khác chiếm giữ các sơn cốc cùng khe núi; càng tiến sâu, hoàn cảnh càng âm u và nguy hiểm.","theLucLienQuan":["Tiên điện"],"nguon":["@c0861"]},{"id":"ngon-nui-van-doc-than-thu","name":"Ngọn núi Vạn Độc Thần Thụ","cn":"","capDo":"khac","parentId":"son-mach-doc-trung","blurb":"Ngọn núi thấp và rộng, trên đỉnh mọc Vạn Độc Thần Thụ.","detail":"Ngọn núi có bề mặt xù xì như một đạo đài lớn. Chung quanh thần thụ tập trung nhiều độc trùng Chân Thần, còn dưới gốc có thi thể hoặc những sinh linh Thiên Thần đang trầm miên gần chết.","theLucLienQuan":["Tiên điện"],"nguon":["@c0861"]},{"id":"vung-dat-co-duoi-van-doc-than-thu","name":"Vùng đất cổ dưới Vạn Độc Thần Thụ","cn":"","capDo":"gioi-nho","parentId":"ngon-nui-van-doc-than-thu","blurb":"Không gian cổ nằm sau cánh cửa mơ hồ cạnh rễ Vạn Độc Thần Thụ.","detail":"Vùng đất được một trận pháp che phủ và ngăn cách với bên ngoài. Đây là nơi truyền nhân Tiên điện lựa chọn để bế quan giữa tuyệt địa độc trùng.","theLucLienQuan":["Tiên điện"],"nguon":["@c0861"]},{"id":"tieu-thien-dia-sau-van-doc-than-thu","name":"Tiểu thiên địa sau Vạn Độc Thần Thụ","cn":"","capDo":"gioi-nho","parentId":"tien-co","blurb":"Tịnh thổ bí mật nằm sau Vạn Độc Thần Thụ và nhiều tầng phòng hộ.","detail":"Nơi này được bảo vệ bởi độc quang, đàn độc trùng cùng cổ trận. Bên trong có đường lát thần thạch, rừng trúc, dòng suối và linh khí nồng đậm như tiên cảnh.","theLucLienQuan":["Tiên điện"],"nguon":["@c0862"]},{"id":"rung-truc-tia","name":"Rừng trúc tía","cn":"","capDo":"khac","parentId":"tieu-thien-dia-sau-van-doc-than-thu","blurb":"Nơi Đế Trùng bế quan trên Ngộ Đạo thạch trong tiểu thiên địa.","detail":"Rừng trúc được cổ trận Tiên điện bảo vệ, tập trung Ngộ Đạo thạch, máu Tiên, cốt thư cảm ngộ, bán thần dược, thánh dịch và thần đan phục vụ việc bế quan.","theLucLienQuan":["Tiên điện"],"nguon":["@c0862"]},{"id":"thanh-quang-minh","name":"Thành Quang Minh","cn":"","capDo":"thanh","parentId":"quang-minh-gioi","blurb":"Thành trì nơi Đế Trùng công khai thách Hoang quyết chiến sau khi chữa thương.","detail":"Đế Trùng đứng trên đầu thành gọi Hoang ra giao chiến, sau đó nhận được tin đối thủ đang ở Thanh Linh giới và lập tức lên đường truy sát.","theLucLienQuan":["Tiên điện"],"nguon":["@c0863"]},{"id":"noi-giao-giua-ba-ngan-con-duong-da","name":"Nơi giao giữa ba ngàn con đường đá","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Điểm giao trên ba ngàn con đường đá được nhóm Thạch Hạo chọn làm nơi bế quan và bố trí kế hoạch bắt giữ thứ không rõ.","detail":"Thạch Hạo dự định trở lại khu vực này để bế quan tu ra tiên khí. Những người đồng hành sẽ cùng bố trí trận pháp, chờ hiện tượng không rõ xuất hiện rồi tìm cách bắt sống và nghiên cứu.","theLucLienQuan":[],"nguon":["@c0866"]},{"id":"ba-ngan-con-duong-da","name":"Ba ngàn con đường đá","cn":"","aliases":["Ba ngàn đường cổ","Con đường ba ngàn tảng đá","Ba ngàn đường đá"],"capDo":"khac","parentId":null,"blurb":"Khu vực có các con đường phát ra hàng nghìn luồng phù văn hỏa diễm và tiếng tụng kinh.","detail":"Thạch Hạo chọn nơi đây làm chỗ bế quan, dùng ánh lửa đại đạo nung luyện chân ngã. Nhóm đồng hành dựng hàng chục sát trận xung quanh, nhưng chiếc đèn cổ mang điềm xấu vẫn xuyên qua và dẫn tới hai sinh linh sương xám.","theLucLienQuan":[],"nguon":["@c0867","@c0868"]},{"id":"khe-hu-khong-ngoai-ba-ngan-con-duong-da","name":"Khe hư không ngoài ba ngàn con đường đá","cn":"","capDo":"khac","parentId":"ba-ngan-con-duong-da","blurb":"Khe lớn trên trời được Thanh Nguyệt diễm làm hiện ra khi truy tìm dấu vết của hai sinh linh cổ.","detail":"Khe hư không nằm bên ngoài ba ngàn con đường đá, cho thấy hai sinh linh mặc giáp đồng tới từ hư không chứ không xuất hiện từ lòng đất. Nó dần khép lại và biến mất khi Thanh Y thu hồi Thanh Nguyệt diễm.","theLucLienQuan":[],"nguon":["@c0868"]},{"id":"vet-rach-hu-khong","name":"Vết rách hư không","cn":"","capDo":"khac","parentId":"ba-ngan-con-duong-da","blurb":"Một vết rách lớn trong hư không xuất hiện gần ba ngàn con đường đá. Các bóng mờ của sát kiếp lần lượt tiến vào đây rồi biến mất.","detail":"Sau khi tiên khí của Thạch Hạo phân tán và không còn hiển lộ, sương xám tan đi, những sinh linh ngang sức hắn rút vào vết rách hư không và biến mất.","theLucLienQuan":[],"nguon":["@c0869"]},{"id":"cac-tieu-thien-the-gioi-lan-can","name":"Các tiểu thiên thế giới lân cận","cn":"","capDo":"gioi-nho","parentId":"tien-co","blurb":"Những tiểu thiên thế giới ở gần ba ngàn con đường đá và cảm nhận được dao động từ cuộc vượt ải của Thạch Hạo.","detail":"Khi ba ngàn phù văn đại đạo phát sáng và hóa thành lửa, dị tượng cùng những gợn sóng đáng sợ lan tới một số tiểu thiên thế giới lân cận.","theLucLienQuan":[],"nguon":["@c0870"]},{"id":"co-thuyen-mau-den","name":"Cổ thuyền màu đen","cn":"","aliases":["Cổ thuyền màu đen nhuốm máu","Thuyền cổ màu đen"],"capDo":"khac","parentId":"vet-rach-hu-khong","blurb":"Một cổ thuyền khổng lồ trôi trong vết rách hư không, có boong trải dài hàng ngàn dặm.","detail":"Không gian trên cổ thuyền tĩnh mịch và không thấy điểm cuối, bao phủ bởi sương mù, huyết tích, hài cốt cùng dấu vết đại chiến. Sâu trong boong có những vại máu lớn như núi và di vật của các sinh linh bí ẩn.","theLucLienQuan":[],"nguon":["@c0873"]},{"id":"te-dan-den-tren-co-thuyen","name":"Tế đàn đen trên cổ thuyền","cn":"","capDo":"khac","parentId":"co-thuyen-mau-den","blurb":"Tế đàn màu đen khổng lồ nằm trên cổ thuyền, có quy mô lớn hơn núi.","detail":"Bề mặt tế đàn phủ hình vẽ cổ và dấu tích đao kiếm. Trên đỉnh có một ao huyết dịch năm màu có thể hiển hóa chiến trường Biên hoang.","theLucLienQuan":[],"nguon":["@c0874"]},{"id":"khoang-thuyen-nhu-mot-the-gioi","name":"Khoang thuyền như một thế giới","cn":"","capDo":"gioi-nho","parentId":"co-thuyen-mau-den","blurb":"Không gian rộng lớn bên trong cổ thuyền màu đen, có quy mô như một thế giới.","detail":"Khoang thuyền chứa sơn hà, núi gãy và vô số thi hài mặc trang phục từ thời Thái cổ cùng Tiên cổ. Dưới chân núi gãy có một chiếc đỉnh đá bị phong ấn và đầy vết nứt.","theLucLienQuan":[],"nguon":["@c0874"]},{"id":"thanh-lon-bien-hoang","name":"Thành lớn Biên hoang","cn":"","capDo":"thanh","parentId":"bien-hoang","blurb":"Tòa thành cổ khổng lồ vắt ngang biên giới tại chiến trường Biên hoang.","detail":"Thành trì vững chắc như một thế giới, được bảy vị Vương cùng những cư dân mặc áo da thú chắp vá bảo vệ. Cả người già, thiếu niên và trẻ nhỏ đều lên đầu tường muốn tham gia cuộc chiến.","theLucLienQuan":[],"nguon":["@c0874"]},{"id":"co-dia-trong-co-thuyen","name":"Cổ địa trong cổ thuyền","cn":"","capDo":"gioi-nho","parentId":"co-thuyen-mau-den","blurb":"Không gian tối tăm, rộng lớn như một thế giới nằm bên trong cổ thuyền màu đen.","detail":"Cổ địa chứa vô số thi hài, binh khí mục nát, một ngọn núi đổ, thạch đỉnh phong ấn và dấu vết của trận chiến từ thời đại xa xưa. Phần cuối khu vực dẫn tới một vực sâu bị thi thể Vương giả cùng hoa văn cổ phong tỏa.","theLucLienQuan":[],"nguon":["@c0875"]},{"id":"ngon-nui-do","name":"Ngọn núi đổ","cn":"","capDo":"khac","parentId":"co-dia-trong-co-thuyen","blurb":"Một ngọn núi gãy đổ nằm gần thạch đỉnh Thế Giới thạch trong cổ địa.","detail":"Phía sau ngọn núi là phần sâu hơn của cổ địa, nơi tiếng gào hú từ vực sâu truyền tới và con đường dẫn về điểm cuối cổ thuyền.","theLucLienQuan":[],"nguon":["@c0875"]},{"id":"vuc-sau-cuoi-co-thuyen","name":"Vực sâu cuối cổ thuyền","cn":"","capDo":"khac","parentId":"co-dia-trong-co-thuyen","blurb":"Vực đen vô biên nằm tại điểm cuối con đường trong khoang cổ thuyền.","detail":"Vực sâu không thấy đáy, liên tục phát ra tiếng gào hú và khí tức đáng sợ. Cửa vực bị hoa văn cổ cùng thi thể một Vương giả trấn thủ Biên hoang phong tỏa, khiến Thạch Hạo nghi ngờ ngọn nguồn của các hiện tượng kỳ lạ nằm bên dưới.","theLucLienQuan":[],"nguon":["@c0875"]},{"id":"day-nui-den","name":"Dãy núi đen","cn":"","capDo":"khac","parentId":"vuc-sau-cuoi-co-thuyen","blurb":"Dãy núi đen nằm ở đường chân trời bên trong vực sâu, trên mỗi ngọn núi đều có ánh đèn đỏ như máu. Đại quân xác cổ và nhiều nhân kiệt cổ đại xuất hiện từ khu vực này.","detail":"Hàng ngàn hàng vạn xác cổ tràn ra khỏi dãy núi đen, trong đó có các chí tôn trẻ tuổi thuộc nhiều thời kỳ. Sâu hơn trong núi còn có những cường giả trung niên mang khí tức mạnh hơn nhiều nhưng chưa trực tiếp tham chiến.","theLucLienQuan":[],"nguon":["@c0876"]},{"id":"vuc-sau-tren-thuyen-co-mau-den","name":"Vực sâu trên thuyền cổ màu đen","cn":"","capDo":"khac","parentId":"co-thuyen-mau-den","blurb":"Vực sâu chứa khí đen, quy tắc kỳ lạ và quái thi bạo động. Thi thể của Vương giả trấn thủ Biên hoang nằm phía trên, tiếp tục dùng thần lực còn sót lại để trấn áp nơi này.","detail":"Khí đen từ vực sâu điều động các cường giả trẻ tuổi, cường giả trung niên và vô số quái thi vây giết Thạch Hạo. Gợn sóng vàng từ thi thể vị Vương phá tan các đòn công kích và quy tắc kỳ lạ, trong khi chữ Tội bùng cháy cùng ngọn lửa thần bí mở ra đường thoát khỏi khu vực.","theLucLienQuan":[],"nguon":["@c0877"]},{"id":"vung-co-duyen-chua-lo-ten","name":"Vùng cơ duyên chưa lộ tên","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Một vùng đất thu hút những sơ đại mạnh nhất và quái thai cổ đại tới tìm kiếm vận may.","detail":"Ninh Xuyên từng lấy được một chiếc xương tay còn sức sống tại đây, còn Thập Quan vương đoạt được một cây non Tiên đạo. Tào Vũ Sinh chuẩn bị dẫn nhóm Thạch Hạo tới nơi này.","theLucLienQuan":[],"nguon":["@c0879"]},{"id":"tang-gioi","name":"Táng giới","cn":"","capDo":"gioi-nho","parentId":"tien-co","blurb":"Tiểu thiên thế giới thần bí trong Tiên cổ, nơi người bình thường khó có thể tiến vào.","detail":"Táng giới có núi Đoạn Thiên và thu hút nhiều sơ đại mạnh nhất, quái thai cổ đại cùng các bộ lạc bản địa Tiên cổ. Tào Vũ Sinh phải dùng cốt khí che thiên cơ trước khi dẫn nhóm Thạch Hạo tới đây.","theLucLienQuan":[],"nguon":["@c0880"]},{"id":"nui-doan-thien","name":"Núi Đoạn Thiên","cn":"","capDo":"khac","parentId":"tang-gioi","blurb":"Ngọn núi cổ trong Táng giới tỏa ra khí tức Tiên đạo.","detail":"Khí tức Tiên đạo tại đây bồi bổ tia tiên khí trong cơ thể Thạch Hạo. Giữa nhiều dấu vết khí tức, hắn cảm nhận một tia phảng phất như thuộc về Liễu Thần.","theLucLienQuan":[],"nguon":["@c0880"]},{"id":"rung-da-do","name":"Rừng đá đỏ","cn":"","capDo":"khac","parentId":"tang-gioi","blurb":"Một cổ địa nổi tiếng trong Táng giới, nơi từng có bảo vật xuất thế. Nhóm Thạch Hạo chứng kiến đồng bảy màu được khai quật tại đây.","detail":"Rừng đá có nhiều khối đá màu đỏ và được biết đến như một địa điểm từng xuất hiện di vật quý. Thạch Hạo dùng Võ đạo Thiên nhãn tìm kiếm nhưng không phát hiện bảo vật còn sót lại, trong khi một cường giả khác khai quật được đồng bảy màu.","theLucLienQuan":[],"nguon":["@c0881"]},{"id":"ho-troi","name":"Hố trời","cn":"","capDo":"khac","parentId":"tang-gioi","blurb":"Một khu vực có đất đá nhiễm máu, cực kỳ cứng chắc và có thể ngăn cản thần thức. Nơi này từng lưu giữ xương tay Tiên của Ninh Xuyên và còn chôn một nhà đá mang phù văn sức sống.","detail":"Hố trời nằm cách rừng đá đỏ khoảng tám trăm dặm đường đi của nhóm Thạch Hạo. Đất đá tại đây nhiễm máu kỳ lạ, khó phá vỡ và che khuất sự dò xét của thần thức; Võ đạo Thiên nhãn nhìn xuyên xuống sâu và phát hiện một nhà đá có phù văn sức sống vô cùng rực rỡ.","theLucLienQuan":[],"nguon":["@c0881"]},{"id":"thach-dien-duoi-ho-troi","name":"Thạch điện dưới hố trời","cn":"","capDo":"khac","parentId":"ho-troi","blurb":"Một thạch điện nhỏ từ kỷ nguyên trước nằm sâu dưới hố trời, mang khí tức thần thánh và lưu lại dấu tay chứa đại đạo.","detail":"Thạch điện bị chôn sâu dưới địa tầng, cấm chế cùng đạo văn đã suy tàn do thời gian và dấu tay khủng khiếp. Thạch Hạo dùng Tiên kiếm Đại La cắt mở kiến trúc này để tiến vào gian phòng chứa di thể Tiên cổ.","theLucLienQuan":["Thiên quốc"],"nguon":["@c0882"]},{"id":"thach-that-chua-di-the-tien-co","name":"Thạch thất chứa di thể Tiên cổ","cn":"","capDo":"khac","parentId":"thach-dien-duoi-ho-troi","blurb":"Gian phòng trong thạch điện nơi một sinh linh Tiên cổ từng bị bàn tay từ vực ngoại đánh chết.","detail":"Thạch thất chứa bộ xương trắng trong suốt, huyết thanh phát sáng và mưa ánh sáng giàu khí tức Tiên đạo. Di thể tại đây phản chấn những kẻ mạo phạm, còn dấu tay trên ngực tái hiện kỳ cảnh về cái chết của sinh linh cổ.","theLucLienQuan":["Thiên quốc"],"nguon":["@c0882"]},{"id":"ao-hon-don","name":"Ao Hỗn độn","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi chứa chất lỏng thần bí mà Cổ Thánh tử phát hiện, dùng để tôi luyện thân thể đến cực hạn.","detail":"Ao Hỗn độn chứa chất lỏng thần bí được Cổ Thánh tử tìm thấy và dùng để bôi lên thân thể cường hóa bản thân. Móng vuốt Kim văn Bạch Hổ cũng từng được ngâm trong chất lỏng này. Thỏ nhỏ tỏ ra thèm muốn cơ duyên ở nơi này.","theLucLienQuan":["Thần miếu"],"nguon":["@c0884"]},{"id":"tang-thanh","name":"Táng thành","cn":"葬城","capDo":"thanh","parentId":"tang-gioi","blurb":"Một trong bốn cổ địa lớn của Táng giới, không có tường thành mà giống phố chợ khổng lồ ghép từ đường phố, kiến trúc, núi đá và vùng cây cối.","detail":"Táng thành là một trong bốn cổ địa lớn của Táng giới. Nơi đây không có tường thành mà giống một phố chợ khổng lồ được ghép từ đường phố, kiến trúc, núi đá và vùng cây cối. Tập trung đông người ngoại lai lẫn đông đảo dân bản địa, bao gồm những chủng tộc có dấu vết từ kỷ nguyên Tiên cổ như Nhân Mã tộc và Cổ Ma tộc. Thạch Hạo cảm ứng được một cao thủ cực kỳ đáng sợ trong thành.","theLucLienQuan":["Thần miếu","Thiên quốc","Nhân Mã tộc","Cổ Ma tộc"],"nguon":["@c0885"]},{"id":"khu-pho-cho-tang-thanh","name":"Khu phố chợ của người ngoài tại Táng thành","cn":"","capDo":"khac","parentId":"tang-thanh","blurb":"Khu phố chợ trao đổi kỳ trân trong Táng thành, không có cư dân bản địa; bị vụ nổ cốt kiếm Tích Huyết san bằng và gây nhiều thương vong.","detail":"Khu vực buôn bán tấp nập của sinh linh từ bên ngoài tới Táng thành, nơi Thiên quốc cho nổ pháp khí Thiên Thần san bằng cả khu phố và giết nhiều sinh linh vô tội.","theLucLienQuan":["Thiên quốc"],"nguon":["@c0886"]},{"id":"vung-nui-do-dam-tang-thanh","name":"Vùng núi đỏ đậm trong Táng thành","cn":"","capDo":"khac","parentId":"tang-thanh","blurb":"Khu vực rộng lớn bị tiên huyết từ đại chiến cổ đại nhuộm đỏ, có nhiều sinh linh tìm kiếm cơ duyên, lòng đất bất thường từng xuất hiện nửa bộ tiên kinh.","detail":"Vùng núi rộng lớn trong Táng thành, đất đá bị tiên huyết nhuộm đỏ sậm từ đại chiến thời cổ. Lòng đất nơi đây từng có người đào được nửa bộ tiên kinh, và manh mối trong cốt thư bằng ngọc thạch cũng dẫn Thập Quan vương tới giành được cây nhỏ Tiên đạo.","theLucLienQuan":[],"nguon":["@c0886"]},{"id":"cam-dia-bang-tuyet","name":"Cấm địa băng tuyết","cn":"","capDo":"khac","parentId":null,"blurb":"Cấm địa gắn với quái thai cổ đại Quân Đạo, được nhắc tới khi Long Vũ giới thiệu lai lịch chủ nhân của mình.","detail":"Cấm địa nơi Quân Đạo trú ngụ, được Long Vũ nhắc tới trong cuộc bàn bạc kết minh.","theLucLienQuan":[],"nguon":["@c0886"]},{"id":"dong-phu-co-trong-nui-tham","name":"Động phủ cổ trong núi thẳm","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Động phủ cổ trong một tiểu thiên thế giới không rõ tên, nơi Quân Đạo gặp Đọa Thần tử bàn bạc và cả hai lần lượt bế quan vượt cửa ải.","detail":"Nằm trong vùng đất cổ thuộc một tiểu thiên thế giới không rõ tên. Quân Đạo tại đây quan sát trạng thái tiên khí gần thành hình của Đọa Thần tử, bàn về sự biến mất của hiện tượng kỳ lạ khi vượt cửa ải, và tự mình bế quan một ngày để thử vượt cửa ải.","theLucLienQuan":[],"nguon":["@c0887"]},{"id":"hac-uyen","name":"Hắc Uyên","cn":"黑渊","capDo":"khac","parentId":"tang-thanh","blurb":"Vực sâu đen kịt đường kính khoảng vạn trượng nằm ở trung tâm Táng thành, được coi là nơi đáng sợ nhất Táng giới.","detail":"Hắc Uyên là một vực thẳm không thấy đáy tại trung tâm Táng thành. Nơi đây áp chế hoàn toàn phi hành, nuốt thần thức và hạn chế tầm nhìn — ngay cả Thiên nhãn võ đạo cũng chỉ nhìn được khoảng trăm trượng. Vách đá trong vực có phù văn bất định, sẽ phát sáng và uy hiếp người thâm nhập ở độ sâu lớn. Ngưỡng an toàn là khoảng một trăm trượng; vượt qua đó, bất kỳ ai rơi xuống đều không thể bay lên dù toàn thân phát sáng. Từ đáy vực thỉnh thoảng phát ra hào quang khiến người ta suy đoán có Tiên khí hoặc thần vật bị che giấu, thậm chí có thể là một thế giới Trung Thiên bị phong ấn. Các chí cường giả cổ đại từng liên thủ tiến vào nhưng không ai trở về. Dân bản địa như Nhân Mã tộc và Cổ Ma tộc canh giữ quanh vực. Thạch Hạo một mình trèo xuống đạt độ sâu hơn một ngàn ba trăm trượng, phát hiện dấu vết đại chiến của Liễu Thần gồm hai lá liễu xanh trong khe đá, rãnh xuyên thủng vách đá và máu khô.","theLucLienQuan":["nhan-ma-toc","co-ma-toc"],"nguon":["@c0888","@c0893"]},{"id":"the-gioi-trung-thien-bi-phong-an","name":"Thế giới Trung Thiên bị phong ấn","cn":"中天世界","capDo":"gioi-nho","parentId":"hac-uyen","blurb":"Không gian được suy đoán có thể nằm sâu dưới Hắc Uyên, chứa luồng tiên khí phát sáng.","detail":"Theo suy đoán của các đại năng quan sát Hắc Uyên, luồng hào quang phát ra từ đáy vực có thể bắt nguồn từ một thế giới Trung Thiên đã bị phong ấn nằm rất sâu bên dưới. Chưa có ai xác nhận được sự tồn tại thực sự của không gian này.","theLucLienQuan":[],"nguon":["@c0888"]},{"id":"vuc-sau-co","name":"Vực sâu cổ","cn":"","capDo":"khac","parentId":"co-thuyen-mau-den","blurb":"Vực sâu khoảng mười vạn trượng nằm cuối cổ thuyền màu đen, vách đá chứa phù văn và xung kích nguy hiểm, dọc đường lưu dấu tích chiến đấu của các cường giả vô thượng Tiên cổ.","detail":"Dọc vách vực có lôi điện tồn tại, vảy và lông Côn Bằng, chân vũ có thể thuộc Phượng, máu tím, cành liễu vàng của Liễu Thần ghim xương sinh linh. Vách đá chứa phù văn vô thượng có thể tạo thành trận pháp cái thế. Đáy vực phủ vô tận hài cốt của những cường giả thám hiểm thất bại.","theLucLienQuan":[],"nguon":["@c0889"]},{"id":"day-vuc-sau","name":"Đáy vực sâu","cn":"","capDo":"khac","parentId":"vuc-sau-co","blurb":"Khu vực đáy vực mười vạn trượng phủ đầy hài cốt, trung tâm được giữ sạch để đặt tế đàn cổ.","detail":"Hài cốt vô tận bao phủ đáy vực, chỉ có khu vực trung tâm sạch sẽ nơi đặt tế đàn cổ bị hư hại. Tế đàn bảo tồn bảo huyết Tiên đạo nhiều màu và có thể làm thời không vặn vẹo.","theLucLienQuan":[],"nguon":["@c0889"]},{"id":"tien-lo-tren-te-dan","name":"Tiên lộ trên tế đàn","cn":"","capDo":"khac","parentId":"day-vuc-sau","blurb":"Con đường thời không mà Thạch Hạo nhận định là lối những người sống sót sau thất bại kỷ nguyên Tiên cổ dùng để rời đi sang một thiên địa không rõ.","detail":"Tế đàn hiện cảnh chín con rồng kéo quan tài đồng phá phong ấn rời khỏi nơi đây. Thạch Hạo liên hệ cảnh tượng này với sự diệt vong của kỷ nguyên Tiên cổ. Cũng là nơi chiếc đỉnh ba chân hai tai đẫm máu đang cố tìm tới để giáng lâm.","theLucLienQuan":[],"nguon":["@c0889"]},{"id":"te-dan-tien-lo","name":"Tế đàn Tiên lộ","cn":"","aliases":["Tế đàn cổ dưới đáy vực"],"capDo":"khac","parentId":"day-vuc-sau","blurb":"Tế đàn truyền tống cổ xưa tàn khuyết nằm dưới đáy vực sâu trong cổ thuyền màu đen, nơi chiếc đỉnh ba chân hai tai thần bí hiển hóa và quy tắc thời không vận hành hỗn loạn.","detail":"Tế đàn mất một nửa từ cuộc đại chiến vạn cổ, vẫn phát ra sức mạnh làm thời gian tiến hoặc lùi cực nhanh, không gian rạn nứt. Sinh linh tiếp cận có thể bị già hóa, trẻ hóa hoặc bị xóa bỏ hoàn toàn. Chiếc đỉnh ba chân hai tai thần bí xuyên qua quy tắc thời không hiển hóa mờ ảo trên tế đàn này. Các khe nứt hư không quanh tế đàn chứa thi thể cổ thuộc nhiều niên đại khác nhau.","theLucLienQuan":[],"nguon":["@c0890"]},{"id":"vuc-sau-tang-thanh","name":"Vực sâu tại Táng thành","cn":"","capDo":"khac","parentId":"tang-thanh","blurb":"Vực sâu tại Táng thành là cấm địa có nguy hiểm tăng theo độ sâu.","detail":"Vách đá trong vực sâu phát ra phù văn nguy hiểm hơn khi đi xuống. Phần lớn tu sĩ chỉ xuống hơn hai ngàn trượng, gần như không ai vượt ba ngàn trượng, còn Thạch Hạo xuống tới mười vạn trượng và thu được nhiều thần liệu.","theLucLienQuan":["Nhân Mã tộc","Bát tí Hồn tộc","Cổ Ma tộc"],"nguon":["@c0891"]},{"id":"khu-dau-gia-tang-thanh","name":"Khu đấu giá Táng thành","cn":"","capDo":"khac","parentId":"tang-thanh","blurb":"Khu đấu giá Táng thành là khu kiến trúc bằng ngọc thạch đông đúc, có phòng đấu giá lớn nhất thành.","detail":"Tại khu đấu giá xuất hiện tin tức về Thiên Thần quả. Đây cũng là nơi Thạch Hạo chạm mặt Đọa Thần tử.","theLucLienQuan":[],"nguon":["@c0891"]},{"id":"phong-dau-gia-lon-nhat-tang-thanh","name":"Phòng đấu giá lớn nhất Táng thành","cn":"","capDo":"khac","parentId":"khu-dau-gia-tang-thanh","blurb":"Phòng đấu giá lớn nhất Táng thành là cung điện nơi Thạch Hạo bị Đọa Thần tử chặn đường.","detail":"Phòng đấu giá có thềm ngọc xanh và cầu vòm ngọc trắng. Thạch Hạo định vào tìm tài nguyên trước khi gặp Đọa Thần tử ở bên ngoài.","theLucLienQuan":[],"nguon":["@c0891"]},{"id":"thanh-duong-phong-dau-gia-di-toc","name":"Thánh đường Phòng đấu giá Dị tộc","cn":"","capDo":"khac","parentId":"phong-dau-gia-lon-nhat-tang-thanh","blurb":"Đại điện đấu giá lộng lẫy tại Táng thành, có không gian bên trong rộng hơn nhiều so với vẻ ngoài. Nơi đây đủ sức chứa hàng chục vạn sinh linh.","detail":"Pháp tắc không gian được bố trí trong thánh đường để mở rộng nội bộ. Ghế, thềm đá, cột và khán đài đều được làm từ nhiều loại mỹ ngọc.","theLucLienQuan":["Phòng đấu giá Dị tộc"],"nguon":["@c0892"]},{"id":"dong-phu-tien-gia","name":"Động phủ Tiên gia","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Động phủ có khả năng chứa tạo hóa lớn cuối cùng của Tiên cổ.","detail":"Dân bản địa không thể tùy tiện đặt chân tới khu vực này. Cây nhỏ Tiên đạo của Thập Quan vương có khả năng bắt nguồn từ vùng bên ngoài động phủ.","theLucLienQuan":["Dân bản địa Tiên cổ"],"nguon":["@c0893"]},{"id":"chien-truong-co-ngoai-tang-thanh","name":"Chiến trường cổ ngoài Táng thành","cn":"","capDo":"khac","parentId":"tang-gioi","blurb":"Chiến trường cổ nơi Thạch Hạo giao chiến với Đọa Thần tử.","detail":"Mặt đất đỏ sậm do máu sinh linh vô thượng nhuộm thành, sát khí và sương mù dày đặc.","theLucLienQuan":[],"nguon":["@c0893"]},{"id":"tinh-tho-than-bi-tho-co-to-te-linh","name":"Tịnh thổ thần bí thờ cổ tổ Tế linh","cn":"","capDo":"vuc","parentId":"tien-co","blurb":"Tịnh thổ nơi thờ cành liễu vàng còn sinh cơ.","detail":"Cành liễu vàng được cắm trong Dòng suối sinh mệnh tại đây nhưng đã lâu chưa thức tỉnh.","theLucLienQuan":["Dân bản địa Tiên cổ","Bát Tí Hồn tộc"],"nguon":["@c0893"]},{"id":"vo-dai-tien-dao","name":"Võ đài Tiên đạo","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Võ đài dành cho cuộc tranh bá của các cường giả hàng đầu Tiên cổ.","detail":"Người chủ trì liên hệ võ đài với con đường tìm kiếm tạo hóa lớn nhất của Tiên cổ.","theLucLienQuan":[],"nguon":["@c0893"]},{"id":"di-tich-duoi-long-dat-tu-ky-nguyen-tien-co","name":"Di tích dưới lòng đất từ kỷ nguyên Tiên cổ","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Di tích được tương truyền là nơi Đọa Thần lĩnh phát hiện Đọa Thần ấn.","detail":"Đây là di tích dưới lòng đất thuộc kỷ nguyên Tiên cổ, gắn với nguồn gốc được truyền lại của tuyệt học Đọa Thần ấn.","theLucLienQuan":["Đọa Thần lĩnh"],"nguon":["@c0894"]},{"id":"chien-truong-co","name":"Chiến trường cổ","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi Thạch Hạo và Đọa Thần tử quyết chiến.","detail":"Chiến trường cổ bị vòng xoáy đen, Cặp cánh Quang Ám và các đòn giao chiến phá nát, khiến núi non cùng mặt đất sụp đổ.","theLucLienQuan":[],"nguon":["@c0895"]},{"id":"thuyen-co-mau-den","name":"Chiếc thuyền cổ màu đen","cn":"","capDo":"khac","parentId":null,"blurb":"Chiếc thuyền cổ được Thạch Hạo suy đoán có liên quan đến biến cố trong bước tiến cảnh giới mới.","detail":"Thạch Hạo cho rằng việc leo lên chiếc thuyền cổ màu đen đã dẫn tới biến cố không rõ mà hắn từng phải chống lại.","theLucLienQuan":[],"nguon":["@c0895"]},{"id":"chien-truong-doa-than-tu","name":"Chiến trường Đọa Thần tử","cn":"","capDo":"vuc","parentId":"tien-co","blurb":"Chiến trường nơi Đọa Thần tử để lại thân thể và bảo vật.","detail":"Kiếm thai Đại La hấp thu tiên kim bảy màu tại đây, sau đó Thạch Hạo bắt Long Vũ để truy tìm Quân Đạo.","theLucLienQuan":["Đọa Thần lĩnh"],"nguon":["@c0897"]},{"id":"bien-gioi-khu-khong-nguoi","name":"Biên giới khu không người","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực ngoại giới nơi các tu sĩ theo dõi Tiên cổ.","detail":"Các tu sĩ các giáo theo dõi hình ảnh và diễn biến từ Tiên cổ tại khu vực này.","theLucLienQuan":[],"nguon":["@c0897"]},{"id":"hang-co-quan-dao","name":"Hang cổ Quân Đạo","cn":"","capDo":"khac","parentId":null,"blurb":"Động phủ nằm sâu trong dãy núi cổ, được trận pháp bảo vệ.","detail":"Hang cổ có khí hỗn độn, trận pháp bảo vệ và kho tàng tu luyện của Quân Đạo; nơi đây bị Thạch Hạo phá trận, đánh tan phòng tuyến và buộc Quân Đạo rút lui.","theLucLienQuan":["Sư môn của Quân Đạo"],"nguon":["@c0897"]},{"id":"vung-nui-co-co-khi-hon-don","name":"Vùng núi cổ có khí hỗn độn","cn":"","capDo":"vuc","parentId":null,"blurb":"Địa vực trời xanh và linh khí bao phủ, chứa hang cổ Quân Đạo.","detail":"Vùng núi cổ có khói mỏng và linh khí bao phủ, bên trong có hang cổ nơi Quân Đạo ẩn cư.","theLucLienQuan":[],"nguon":["@c0897"]},{"id":"hang-co","name":"Hang cổ","cn":"","capDo":"khac","parentId":null,"blurb":"Hang cổ chứa nhiều bảo vật, trong đó có Vạn Vật thổ và Hoàng Văn thạch.","detail":"Sâu trong hang cổ có bảo quang, khí lành và nhiều thiên tài địa bảo. Nhóm Thạch Hạo phát hiện Vạn Vật thổ và Hoàng Văn thạch tại đây.","theLucLienQuan":[],"nguon":["@c0898"]},{"id":"tran-gioi","name":"Trận giới","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Trận giới là nơi Tào Vũ Sinh dự định đến để cảm ngộ vạn trận.","detail":"Tào Vũ Sinh chọn đến Trận giới để lĩnh hội vạn trận và tìm cách bước ra bước cuối cùng.","theLucLienQuan":[],"nguon":["@c0898"]},{"id":"tieu-thien-the-gioi","name":"Tiểu thiên thế giới","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Một số tiểu thiên thế giới nghe tin về chiến tích của Thạch Hạo.","detail":"Tin Thạch Hạo giết Đọa Thần tử và đuổi Quân Đạo gây chấn động tại một số tiểu thiên thế giới.","theLucLienQuan":[],"nguon":["@c0898"]},{"id":"ven-ho-linh-khi","name":"Ven hồ linh khí","cn":"","capDo":"khac","parentId":null,"blurb":"Ven hồ linh khí là nơi Đả Thần Thạch làm sạch thi thể Tiên.","detail":"Đả Thần Thạch kéo thi thể đầu rồng thân hạc tới ven hồ linh khí để làm sạch, chuẩn bị cho bữa ăn của nhóm.","theLucLienQuan":[],"nguon":["@c0898"]},{"id":"ho-nuoc-trong-xanh","name":"Hồ nước trong xanh","cn":"","capDo":"khac","parentId":null,"blurb":"Hồ nước có linh khí liên tục bốc lên, nơi nhóm Thạch Hạo ăn uống và cảm ngộ đại đạo.","detail":"Nhóm Thạch Hạo tổ chức bữa tiệc bên hồ nước trong xanh. Ở bờ đối diện, một chim trắng giống Tuyết Hoàng xuất hiện rồi hóa thành thiếu nữ tóc bạc.","theLucLienQuan":[],"nguon":["@c0899"]},{"id":"cung-dien-chi-ton","name":"Cung điện Chí tôn","cn":"","capDo":"khac","parentId":null,"blurb":"Địa điểm có manh mối được Tuyết Lâm phát hiện sau khi trở về Thượng giới.","detail":"Thạch Hạo muốn biết vị trí Cung điện Chí tôn và đề nghị dùng một vận may lớn cùng một phần Tiên thể để trao đổi thông tin.","theLucLienQuan":[],"nguon":["@c0900"]}]};
